def _set_accelerators(
    self,
    accelerators: Union[None, str, Dict[str, int]],
    accelerator_args: Optional[Dict[str, str]],
) -> None:
    """Sets accelerators.

    Args:
        accelerators: A string or a dict of accelerator types to counts.
        accelerator_args: A dict of accelerator types to args.
    """
    if accelerators is not None:
        if isinstance(accelerators, str):  # Convert to Dict[str, int].
            if ":" not in accelerators:
                accelerators = {accelerators: 1}
            else:
                splits = accelerators.split(":")
                parse_error = (
                    'The "accelerators" field as a str '
                    "should be <name> or <name>:<cnt>. "
                    f"Found: {accelerators!r}"
                )
                if len(splits) != 2:
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError(parse_error)
                try:
                    num = float(splits[1])
                    num = int(num) if num.is_integer() else num
                    accelerators = {splits[0]: num}
                except ValueError:
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError(parse_error) from None

        # Ignore check for the local cloud case.
        # It is possible the accelerators dict can contain multiple
        # types of accelerators for some on-prem clusters.
        if not isinstance(self._cloud, clouds.Local):
            assert len(accelerators) == 1, accelerators

        # Canonicalize the accelerator names.
        accelerators = {
            accelerator_registry.canonicalize_accelerator_name(acc): acc_count
            for acc, acc_count in accelerators.items()
        }

        acc, _ = list(accelerators.items())[0]
        if "tpu" in acc.lower():
            if self.cloud is None:
                self._cloud = clouds.GCP()
            assert self.cloud.is_same_cloud(clouds.GCP()), "Cloud must be GCP."
            if accelerator_args is None:
                accelerator_args = {}
            use_tpu_vm = accelerator_args.get("tpu_vm", False)
            if use_tpu_vm:
                tpu_utils.check_gcp_cli_include_tpu_vm()
            if self.instance_type is not None and use_tpu_vm:
                if self.instance_type != "TPU-VM":
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError(
                            "Cannot specify instance type"
                            f' (got "{self.instance_type}") for TPU VM.'
                        )
            if "runtime_version" not in accelerator_args:
                if use_tpu_vm:
                    accelerator_args["runtime_version"] = "tpu-vm-base"
                else:
                    accelerator_args["runtime_version"] = "2.12.0"
                logger.info(
                    "Missing runtime_version in accelerator_args, using"
                    f' default ({accelerator_args["runtime_version"]})'
                )

    self._accelerators = accelerators
    self._accelerator_args = accelerator_args

def _validate_and_set_region_zone(
    self, region: Optional[str], zone: Optional[str]
) -> None:
    if region is None and zone is None:
        return

    if self._cloud is None:
        # Try to infer the cloud from region/zone, if unique. If 0 or >1
        # cloud corresponds to region/zone, errors out.
        valid_clouds = []
        enabled_clouds = global_user_state.get_enabled_clouds()
        cloud_to_errors = {}
        for cloud in enabled_clouds:
            try:
                cloud.validate_region_zone(region, zone)
            except ValueError as e:
                cloud_to_errors[repr(cloud)] = e
                continue
            valid_clouds.append(cloud)

        if len(valid_clouds) == 0:
            if len(enabled_clouds) == 1:
                cloud_str = f"for cloud {enabled_clouds[0]}"
            else:
                cloud_str = f"for any cloud among {enabled_clouds}"
            with ux_utils.print_exception_no_traceback():
                if len(cloud_to_errors) == 1:
                    # UX: if 1 cloud, don't print a table.
                    hint = list(cloud_to_errors.items())[0][-1]
                else:
                    table = log_utils.create_table(["Cloud", "Hint"])
                    table.add_row(["-----", "----"])
                    for cloud, error in cloud_to_errors.items():
                        reason_str = "\n".join(textwrap.wrap(str(error), 80))
                        table.add_row([str(cloud), reason_str])
                    hint = table.get_string()
                raise ValueError(
                    f"Invalid (region {region!r}, zone {zone!r}) "
                    f"{cloud_str}. Details:\n{hint}"
                )
        elif len(valid_clouds) > 1:
            with ux_utils.print_exception_no_traceback():
                raise ValueError(
                    f"Cannot infer cloud from (region {region!r}, zone "
                    f"{zone!r}). Multiple enabled clouds have region/zone "
                    f"of the same names: {valid_clouds}. "
                    f"To fix: explicitly specify `cloud`."
                )
        logger.debug(
            f"Cloud is not specified, using {valid_clouds[0]} "
            f"inferred from region {region!r} and zone {zone!r}"
        )
        self._cloud = valid_clouds[0]

    # Validate if region and zone exist in the catalog, and set the region
    # if zone is specified.
    self._region, self._zone = self._cloud.validate_region_zone(region, zone)

def _try_validate_instance_type(self) -> None:
    if self.instance_type is None:
        return

    # Validate instance type
    if self.cloud is not None:
        valid = self.cloud.instance_type_exists(self._instance_type)
        if not valid:
            with ux_utils.print_exception_no_traceback():
                raise ValueError(
                    f"Invalid instance type {self._instance_type!r} "
                    f"for cloud {self.cloud}."
                )
    else:
        # If cloud not specified
        valid_clouds = []
        enabled_clouds = global_user_state.get_enabled_clouds()
        for cloud in enabled_clouds:
            if cloud.instance_type_exists(self._instance_type):
                valid_clouds.append(cloud)
        if len(valid_clouds) == 0:
            if len(enabled_clouds) == 1:
                cloud_str = f"for cloud {enabled_clouds[0]}"
            else:
                cloud_str = f"for any cloud among {enabled_clouds}"
            with ux_utils.print_exception_no_traceback():
                raise ValueError(
                    f"Invalid instance type {self._instance_type!r} "
                    f"{cloud_str}."
                )
        if len(valid_clouds) > 1:
            with ux_utils.print_exception_no_traceback():
                raise ValueError(
                    f"Ambiguous instance type {self._instance_type!r}. "
                    f"Please specify cloud explicitly among {valid_clouds}."
                )
        logger.debug(
            f"Cloud is not specified, using {valid_clouds[0]} "
            f"inferred from the instance_type {self.instance_type!r}."
        )
        self._cloud = valid_clouds[0]

def _try_validate_cpus_mem(self) -> None:
    if self.cpus is None and self.memory is None:
        return
    if self.instance_type is not None:
        # The assertion should be true because we have already executed
        # _try_validate_instance_type() before this method.
        # The _try_validate_instance_type() method infers and sets
        # self.cloud if self.instance_type is not None.
        assert self.cloud is not None
        cpus, mem = self.cloud.get_vcpus_mem_from_instance_type(self.instance_type)
        if self.cpus is not None:
            if self.cpus.endswith("+"):
                if cpus < float(self.cpus[:-1]):
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError(
                            f"{self.instance_type} does not have enough "
                            f"vCPUs. {self.instance_type} has {cpus} "
                            f"vCPUs, but {self.cpus} is requested."
                        )
            elif cpus != float(self.cpus):
                with ux_utils.print_exception_no_traceback():
                    raise ValueError(
                        f"{self.instance_type} does not have the requested "
                        f"number of vCPUs. {self.instance_type} has {cpus} "
                        f"vCPUs, but {self.cpus} is requested."
                    )
        if self.memory is not None:
            if self.memory.endswith("+"):
                if mem < float(self.memory[:-1]):
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError(
                            f"{self.instance_type} does not have enough "
                            f"memory. {self.instance_type} has {mem} GB "
                            f"memory, but {self.memory} is requested."
                        )
            elif mem != float(self.memory):
                with ux_utils.print_exception_no_traceback():
                    raise ValueError(
                        f"{self.instance_type} does not have the requested "
                        f"memory. {self.instance_type} has {mem} GB "
                        f"memory, but {self.memory} is requested."
                    )

def _try_validate_disk_tier(self) -> None:
    if self.disk_tier is None:
        return
    if self.disk_tier not in ["high", "medium", "low"]:
        with ux_utils.print_exception_no_traceback():
            raise ValueError(
                f"Invalid disk_tier {self.disk_tier}. "
                'Please use one of "high", "medium", or "low".'
            )
    if self.instance_type is None:
        return
    if self.cloud is not None:
        self.cloud.check_disk_tier_enabled(self.instance_type, self.disk_tier)

def _try_validate_ports(self) -> None:
    if self.ports is None:
        return
    if skypilot_config.get_nested(("aws", "security_group_name"), None) is not None:
        with ux_utils.print_exception_no_traceback():
            raise ValueError(
                "Cannot specify ports when AWS security group name is " "specified."
            )
    if self.cloud is not None:
        self.cloud.check_features_are_supported(
            {clouds.CloudImplementationFeatures.OPEN_PORTS}
        )

def get_cost(self, seconds: float) -> float:
    """Returns cost in USD for the runtime in seconds."""
    hours = seconds / 3600
    # Instance.
    hourly_cost = self.cloud.instance_type_to_hourly_cost(
        self._instance_type, self.use_spot, self._region, self._zone
    )
    # Accelerators (if any).
    if self.accelerators is not None:
        hourly_cost += self.cloud.accelerators_to_hourly_cost(
            self.accelerators, self.use_spot, self._region, self._zone
        )
    return hourly_cost * hours

def get_reservations_available_resources(
    self, specific_reservations: Set[str]
) -> Dict[str, int]:
    """Returns the number of available reservation resources."""
    if self.use_spot:
        # GCP's & AWS's reservations do not support spot instances. We
        # assume other clouds behave the same. We can move this check down
        # to each cloud if any cloud supports reservations for spot.
        return {}
    return self.cloud.get_reservations_available_resources(
        self._instance_type, self._region, self._zone, specific_reservations
    )

def less_demanding_than(
    self,
    other: Union[List["Resources"], "Resources"],
    requested_num_nodes: int = 1,
    check_ports: bool = False,
) -> bool:
    """Returns whether this resources is less demanding than the other.

    Args:
        other: Resources of the launched cluster. If the cluster is
          heterogeneous, it is represented as a list of Resource objects.
        requested_num_nodes: Number of nodes that the current task
          requests from the cluster.
        check_ports: Whether to check the ports field.
    """
    if isinstance(other, list):
        resources_list = [self.less_demanding_than(o) for o in other]
        return requested_num_nodes <= sum(resources_list)
    if self.cloud is not None and not self.cloud.is_same_cloud(other.cloud):
        return False
    # self.cloud <= other.cloud

    if self.region is not None and self.region != other.region:
        return False
    # self.region <= other.region

    if self.zone is not None and self.zone != other.zone:
        return False
    # self.zone <= other.zone

    if self.image_id is not None:
        if other.image_id is None:
            return False
        if other.region is None:
            # Current image_id should be a subset of other.image_id
            if not self.image_id.items() <= other.image_id.items():
                return False
        else:
            this_image = self.image_id.get(other.region) or self.image_id.get(None)
            other_image = other.image_id.get(other.region) or other.image_id.get(
                None
            )
            if this_image != other_image:
                return False

    if (
        self._instance_type is not None
        and self._instance_type != other.instance_type
    ):
        return False
    # self._instance_type <= other.instance_type

    other_accelerators = other.accelerators
    if self.accelerators is not None:
        if other_accelerators is None:
            return False
        for acc in self.accelerators:
            if acc not in other_accelerators:
                return False
            if self.accelerators[acc] > other_accelerators[acc]:
                return False
    # self.accelerators <= other.accelerators

    if (
        self.accelerator_args is not None
        and self.accelerator_args != other.accelerator_args
    ):
        return False
    # self.accelerator_args == other.accelerator_args

    if self.use_spot_specified and self.use_spot != other.use_spot:
        return False

    if self.disk_tier is not None:
        if other.disk_tier is None:
            return False
        if self.disk_tier != other.disk_tier:
            types = ["low", "medium", "high"]
            return types.index(self.disk_tier) < types.index(other.disk_tier)

    if check_ports:
        if self.ports is not None:
            if other.ports is None:
                return False
            self_ports = resources_utils.port_ranges_to_set(self.ports)
            other_ports = resources_utils.port_ranges_to_set(other.ports)
            if not self_ports <= other_ports:
                return False

    # self <= other
    return True

def should_be_blocked_by(self, blocked: "Resources") -> bool:
    """Whether this Resources matches the blocked Resources.

    If a field in `blocked` is None, it should be considered as a wildcard
    for that field.
    """
    is_matched = True
    if blocked.cloud is not None and not self.cloud.is_same_cloud(blocked.cloud):
        is_matched = False
    if (
        blocked.instance_type is not None
        and self.instance_type != blocked.instance_type
    ):
        is_matched = False
    if blocked.region is not None and self._region != blocked.region:
        is_matched = False
    if blocked.zone is not None and self._zone != blocked.zone:
        is_matched = False
    if (
        blocked.accelerators is not None
        and self.accelerators != blocked.accelerators
    ):
        is_matched = False
    return is_matched

def valid_on_region_zones(self, region: str, zones: List[str]) -> bool:
    """Returns whether this Resources is valid on given region and zones"""
    if self.region is not None and self.region != region:
        return False
    if self.zone is not None and self.zone not in zones:
        return False
    if self.image_id is not None:
        if None not in self.image_id and region not in self.image_id:
            return False
    return True

def __setstate__(self, state):
    """Set state from pickled state, for backward compatibility."""
    self._version = self._VERSION

    # TODO (zhwu): Design our persistent state format with `__getstate__`,
    # so that to get rid of the version tracking.
    version = state.pop("_version", None)
    # Handle old version(s) here.
    if version is None:
        version = -1
    if version < 0:
        cloud = state.pop("cloud", None)
        state["_cloud"] = cloud

        instance_type = state.pop("instance_type", None)
        state["_instance_type"] = instance_type

        use_spot = state.pop("use_spot", False)
        state["_use_spot"] = use_spot

        accelerator_args = state.pop("accelerator_args", None)
        state["_accelerator_args"] = accelerator_args

        disk_size = state.pop("disk_size", _DEFAULT_DISK_SIZE_GB)
        state["_disk_size"] = disk_size

    if version < 2:
        self._region = None

    if version < 3:
        self._spot_recovery = None

    if version < 4:
        self._image_id = None

    if version < 5:
        self._zone = None

    if version < 6:
        accelerators = state.pop("_accelerators", None)
        if accelerators is not None:
            accelerators = {
                accelerator_registry.canonicalize_accelerator_name(acc): acc_count
                for acc, acc_count in accelerators.items()
            }
        state["_accelerators"] = accelerators

    if version < 7:
        self._cpus = None

    if version < 8:
        self._memory = None

    image_id = state.get("_image_id", None)
    if isinstance(image_id, str):
        state["_image_id"] = {state.get("_region", None): image_id}

    if version < 9:
        self._disk_tier = None

    if version < 10:
        self._is_image_managed = None

    if version < 11:
        self._ports = None

    if version < 12:
        self._docker_login_config = None

    if version < 13:
        original_ports = state.get("_ports", None)
        if original_ports is not None:
            state["_ports"] = resources_utils.simplify_ports(
                [str(port) for port in original_ports]
            )

    self.__dict__.update(state)

"""Adds Listenbrainz support to Beets."""

import datetime

import musicbrainzngs
import requests

from beets import config, ui
from beets.plugins import BeetsPlugin
from beetsplug.lastimport import process_tracks


class ListenBrainzPlugin(BeetsPlugin):
    """A Beets plugin for interacting with ListenBrainz."""

    data_source = "ListenBrainz"
    ROOT = "http://api.listenbrainz.org/1/"

    def __init__(self):
        """Initialize the plugin."""
        super().__init__()
        self.token = self.config["token"].get()
        self.username = self.config["username"].get()
        self.AUTH_HEADER = {"Authorization": f"Token {self.token}"}
        config["listenbrainz"]["token"].redact = True

    def commands(self):
        """Add beet UI commands to interact with ListenBrainz."""
        lbupdate_cmd = ui.Subcommand(
            "lbimport", help=f"Import {self.data_source} history"
        )

        def func(lib, opts, args):
            self._lbupdate(lib, self._log)

        lbupdate_cmd.func = func
        return [lbupdate_cmd]

    def _lbupdate(self, lib, log):
        """Obtain view count from Listenbrainz."""
        found_total = 0
        unknown_total = 0
        ls = self.get_listens()
        tracks = self.get_tracks_from_listens(ls)
        log.info(f"Found {len(ls)} listens")
        if tracks:
            found, unknown = process_tracks(lib, tracks, log)
            found_total += found
            unknown_total += unknown
        log.info("... done!")
        log.info("{0} unknown play-counts", unknown_total)
        log.info("{0} play-counts imported", found_total)

    def _make_request(self, url, params=None):
        """Makes a request to the ListenBrainz API."""
        try:
            response = requests.get(
                url=url,
                headers=self.AUTH_HEADER,
                timeout=10,
                params=params,
            )
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            self._log.debug(f"Invalid Search Error: {e}")
            return None

    def get_listens(self, min_ts=None, max_ts=None, count=None):
        """Gets the listen history of a given user.

        Args:
            username: User to get listen history of.
            min_ts: History before this timestamp will not be returned.
                    DO NOT USE WITH max_ts.
            max_ts: History after this timestamp will not be returned.
                    DO NOT USE WITH min_ts.
            count: How many listens to return. If not specified,
                uses a default from the server.

        Returns:
            A list of listen info dictionaries if there's an OK status.

        Raises:
            An HTTPError if there's a failure.
            A ValueError if the JSON in the response is invalid.
            An IndexError if the JSON is not structured as expected.
        """
        url = f"{self.ROOT}/user/{self.username}/listens"
        params = {
            k: v
            for k, v in {
                "min_ts": min_ts,
                "max_ts": max_ts,
                "count": count,
            }.items()
            if v is not None
        }
        response = self._make_request(url, params)

        if response is not None:
            return response["payload"]["listens"]
        else:
            return None

    def get_tracks_from_listens(self, listens):
        """Returns a list of tracks from a list of listens."""
        tracks = []
        for track in listens:
            if track["track_metadata"].get("release_name") is None:
                continue
            mbid_mapping = track["track_metadata"].get("mbid_mapping", {})
            # print(json.dumps(track, indent=4, sort_keys=True))
            if mbid_mapping.get("recording_mbid") is None:
                # search for the track using title and release
                mbid = self.get_mb_recording_id(track)
            tracks.append(
                {
                    "album": {
                        "name": track["track_metadata"].get("release_name")
                    },
                    "name": track["track_metadata"].get("track_name"),
                    "artist": {
                        "name": track["track_metadata"].get("artist_name")
                    },
                    "mbid": mbid,
                    "release_mbid": mbid_mapping.get("release_mbid"),
                    "listened_at": track.get("listened_at"),
                }
            )
        return tracks

    def get_mb_recording_id(self, track):
        """Returns the MusicBrainz recording ID for a track."""
        resp = musicbrainzngs.search_recordings(
            query=track["track_metadata"].get("track_name"),
            release=track["track_metadata"].get("release_name"),
            strict=True,
        )
        if resp.get("recording-count") == "1":
            return resp.get("recording-list")[0].get("id")
        else:
            return None

    def get_playlists_createdfor(self, username):
        """Returns a list of playlists created by a user."""
        url = f"{self.ROOT}/user/{username}/playlists/createdfor"
        return self._make_request(url)

    def get_listenbrainz_playlists(self):
        """Returns a list of playlists created by ListenBrainz."""
        resp = self.get_playlists_createdfor(self.username)
        playlists = resp.get("playlists")
        listenbrainz_playlists = []

        for playlist in playlists:
            playlist_info = playlist.get("playlist")
            if playlist_info.get("creator") == "listenbrainz":
                title = playlist_info.get("title")
                playlist_type = (
                    "Exploration" if "Exploration" in title else "Jams"
                )
                if "week of " in title:
                    date_str = title.split("week of ")[1].split(" ")[0]
                    date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()
                else:
                    date = None
                identifier = playlist_info.get("identifier")
                id = identifier.split("/")[-1]
                listenbrainz_playlists.append(
                    {"type": playlist_type, "date": date, "identifier": id}
                )
        return listenbrainz_playlists

    def get_playlist(self, identifier):
        """Returns a playlist."""
        url = f"{self.ROOT}/playlist/{identifier}"
        return self._make_request(url)

    def get_tracks_from_playlist(self, playlist):
        """This function returns a list of tracks in the playlist."""
        tracks = []
        for track in playlist.get("playlist").get("track"):
            tracks.append(
                {
                    "artist": track.get("creator"),
                    "identifier": track.get("identifier").split("/")[-1],
                    "title": track.get("title"),
                }
            )
        return self.get_track_info(tracks)

    def get_track_info(self, tracks):
        """Returns a list of track info."""
        track_info = []
        for track in tracks:
            identifier = track.get("identifier")
            resp = musicbrainzngs.get_recording_by_id(
                identifier, includes=["releases", "artist-credits"]
            )
            recording = resp.get("recording")
            title = recording.get("title")
            artist_credit = recording.get("artist-credit", [])
            if artist_credit:
                artist = artist_credit[0].get("artist", {}).get("name")
            else:
                artist = None
            releases = recording.get("release-list", [])
            if releases:
                album = releases[0].get("title")
                date = releases[0].get("date")
                year = date.split("-")[0] if date else None
            else:
                album = None
                year = None
            track_info.append(
                {
                    "identifier": identifier,
                    "title": title,
                    "artist": artist,
                    "album": album,
                    "year": year,
                }
            )
        return track_info

    def get_weekly_playlist(self, index):
        """Returns a list of weekly playlists based on the index."""
        playlists = self.get_listenbrainz_playlists()
        playlist = self.get_playlist(playlists[index].get("identifier"))
        return self.get_tracks_from_playlist(playlist)

    def get_weekly_exploration(self):
        """Returns a list of weekly exploration."""
        return self.get_weekly_playlist(0)

    def get_weekly_jams(self):
        """Returns a list of weekly jams."""
        return self.get_weekly_playlist(1)

    def get_last_weekly_exploration(self):
        """Returns a list of weekly exploration."""
        return self.get_weekly_playlist(3)

    def get_last_weekly_jams(self):
        """Returns a list of weekly jams."""
        return self.get_weekly_playlist(3)

