def _run_trial(
    study: "optuna.Study",
    func: "optuna.study.study.ObjectiveFuncType",
    catch: Tuple[Type[Exception], ...],
) -> trial_module.FrozenTrial:
    if is_heartbeat_enabled(study._storage):
        optuna.storages.fail_stale_trials(study)

    trial = study.ask()

    state: Optional[TrialState] = None
    value_or_values: Optional[Union[float, Sequence[float]]] = None
    func_err: Optional[Union[Exception, KeyboardInterrupt]] = None
    func_err_fail_exc_info: Optional[Any] = None

    with get_heartbeat_thread(trial._trial_id, study._storage):
        try:
            value_or_values = func(trial)
        except exceptions.TrialPruned as e:
            # TODO(mamu): Handle multi-objective cases.
            state = TrialState.PRUNED
            func_err = e
        except (Exception, KeyboardInterrupt) as e:
            state = TrialState.FAIL
            func_err = e
            func_err_fail_exc_info = sys.exc_info()

    # `_tell_with_warning` may raise during trial post-processing.
    try:
        frozen_trial = _tell_with_warning(
            study=study,
            trial=trial,
            value_or_values=value_or_values,
            state=state,
            suppress_warning=True,
        )
    except Exception:
        frozen_trial = study._storage.get_trial(trial._trial_id)
        raise
    finally:
        if frozen_trial.state == TrialState.COMPLETE:
            study._log_completed_trial(frozen_trial)
        elif frozen_trial.state == TrialState.PRUNED:
            _logger.info("Trial {} pruned. {}".format(frozen_trial.number, str(func_err)))
        elif frozen_trial.state == TrialState.FAIL:
            if func_err is not None:
                _log_failed_trial(
                    frozen_trial,
                    repr(func_err),
                    exc_info=func_err_fail_exc_info,
                    value_or_values=value_or_values,
                )
            elif STUDY_TELL_WARNING_KEY in frozen_trial.system_attrs:
                _log_failed_trial(
                    frozen_trial,
                    frozen_trial.system_attrs[STUDY_TELL_WARNING_KEY],
                    value_or_values=value_or_values,
                )
            else:
                assert False, "Should not reach."
        else:
            assert False, "Should not reach."

    if (
        frozen_trial.state == TrialState.FAIL
        and func_err is not None
        and not isinstance(func_err, catch)
    ):
        raise func_err
    return frozen_trial

def __new__(cls, name, bases, attrs):
    new_class = super().__new__(cls, name, bases, attrs)

    opts = new_class._meta

    if not opts.instance_loader_class:
        opts.instance_loader_class = ModelInstanceLoader

    if opts.model:
        model_opts = opts.model._meta
        declared_fields = new_class.fields

        field_list = []
        for f in sorted(model_opts.fields + model_opts.many_to_many):
            if opts.fields is not None and f.name not in opts.fields:
                continue
            if opts.exclude and f.name in opts.exclude:
                continue

            if f.name in declared_fields:
                # If model field is declared in `ModelResource`, remove it from `declared_fields`
                # to keep exact order of model fields
                field = declared_fields.pop(f.name)
            else:
                field = new_class.field_from_django_field(f.name, f, readonly=False)

            field_list.append(
                (
                    f.name,
                    field,
                )
            )

        # Order as model fields first then declared fields by default
        new_class.fields = OrderedDict([*field_list, *new_class.fields.items()])

        # add fields that follow relationships
        if opts.fields is not None:
            field_list = []
            for field_name in opts.fields:
                if field_name in declared_fields:
                    continue
                if field_name.find("__") == -1:
                    continue

                model = opts.model
                attrs = field_name.split("__")
                for i, attr in enumerate(attrs):
                    verbose_path = ".".join(
                        [opts.model.__name__] + attrs[0 : i + 1]
                    )

                    try:
                        f = model._meta.get_field(attr)
                    except FieldDoesNotExist as e:
                        logger.debug(e, exc_info=e)
                        raise FieldDoesNotExist(
                            "%s: %s has no field named '%s'"
                            % (verbose_path, model.__name__, attr)
                        )

                    if i < len(attrs) - 1:
                        # We're not at the last attribute yet, so check
                        # that we're looking at a relation, and move on to
                        # the next model.
                        if isinstance(f, ForeignObjectRel):
                            model = get_related_model(f)
                        else:
                            if get_related_model(f) is None:
                                raise KeyError(
                                    "%s is not a relation" % verbose_path
                                )
                            model = get_related_model(f)

                if isinstance(f, ForeignObjectRel):
                    f = f.field

                field = new_class.field_from_django_field(
                    field_name, f, readonly=True
                )
                field_list.append((field_name, field))

            new_class.fields.update(OrderedDict(field_list))

    return new_class

