def infer(
    self,
    text,
    stream=False,
    lang=None,
    skip_refine_text=False,
    refine_text_only=False,
    use_decoder=True,
    do_text_normalization=True,
    do_homophone_replacement=True,
    split_text=True,
    max_split_batch=4,
    params_refine_text=RefineTextParams(),
    params_infer_code=InferCodeParams(),
):
    self.context.set(False)

    if split_text and isinstance(text, str):
        if "\n" in text:
            text = text.split("\n")
        else:
            text = re.split(r"(?<=。)|(?<=\.\s)", text)
            nt = []
            if isinstance(text, list):
                for t in text:
                    if t:
                        nt.append(t)
                text = nt
            else:
                text = [text]
        self.logger.info("split text into %d parts", len(text))
        self.logger.debug("%s", str(text))

    if len(text) == 0:
        return []

    res_gen = self._infer(
        text,
        stream,
        lang,
        skip_refine_text,
        refine_text_only,
        use_decoder,
        do_text_normalization,
        do_homophone_replacement,
        split_text,
        max_split_batch,
        params_refine_text,
        params_infer_code,
    )
    if stream:
        return res_gen
    elif not refine_text_only:
        stripped_wavs = []
        thr = np.float32(1e-5)
        for wavs in res_gen:
            for wav in wavs:
                stripped_wavs.append(wav[np.abs(wav) > thr])
        if split_text:
            return [np.concatenate(stripped_wavs)]
        return stripped_wavs
    else:
        return next(res_gen)

def load(
    self,
    recreate: bool = False,
    upsert: bool = True,
    skip_existing: bool = True,
    filters: Optional[Dict[str, Any]] = None,
) -> None:
    """Load the website contents to the vector db"""

    if self.vector_db is None:
        logger.warning("No vector db provided")
        return

    if self.reader is None:
        logger.warning("No reader provided")
        return

    if recreate:
        log_debug("Dropping collection")
        self.vector_db.drop()

    log_debug("Creating collection")
    self.vector_db.create()

    log_info("Loading knowledge base")

    # Given that the crawler needs to parse the URL before existence can be checked
    # We check if the website url exists in the vector db if recreate is False
    urls_to_read = self.urls.copy()
    if not recreate:
        for url in urls_to_read:
            log_debug(f"Checking if {url} exists in the vector db")
            if self.vector_db.name_exists(name=url):
                log_debug(f"Skipping {url} as it exists in the vector db")
                urls_to_read.remove(url)

    num_documents = 0
    for url in urls_to_read:
        if document_list := self.reader.read(url=url):
            # Filter out documents which already exist in the vector db
            if not recreate:
                document_list = [document for document in document_list if not self.vector_db.doc_exists(document)]
                if not document_list:
                    continue
            if upsert and self.vector_db.upsert_available():
                self.vector_db.upsert(documents=document_list, filters=filters)
            else:
                self.vector_db.insert(documents=document_list, filters=filters)
            num_documents += len(document_list)
            log_info(f"Loaded {num_documents} documents to knowledge base")

    if self.optimize_on is not None and num_documents > self.optimize_on:
        log_debug("Optimizing Vector DB")
        self.vector_db.optimize()

def prune_actor_input_schema(input_schema: Dict[str, Any]) -> Tuple[Dict[str, Any], List[str]]:
    """Get the input schema from the Actor build and trim descriptions.

    Args:
        input_schema (Dict[str, Any]): The input schema from the Actor build

    Returns:
        Tuple[Dict[str, Any], List[str]]: A tuple containing the pruned properties and required fields
    """
    properties = input_schema.get("properties", {})
    required = input_schema.get("required", [])

    properties_out: Dict[str, Any] = {}
    for item, meta in properties.items():
        properties_out[item] = {}
        if desc := meta.get("description"):
            properties_out[item]["description"] = (
                desc[:MAX_DESCRIPTION_LEN] + "..." if len(desc) > MAX_DESCRIPTION_LEN else desc
            )
        for key_name in ("type", "default", "prefill", "enum"):
            if value := meta.get(key_name):
                properties_out[item][key_name] = value

    return properties_out, required

def from_callable(cls, c: Callable, strict: bool = False) -> "Function":
    from inspect import getdoc, isasyncgenfunction, signature

    from agno.utils.json_schema import get_json_schema

    function_name = c.__name__
    parameters = {"type": "object", "properties": {}, "required": []}
    try:
        sig = signature(c)
        type_hints = get_type_hints(c)

        # If function has an the agent argument, remove the agent parameter from the type hints
        if "agent" in sig.parameters:
            del type_hints["agent"]
        if "team" in sig.parameters:
            del type_hints["team"]
        # log_info(f"Type hints for {function_name}: {type_hints}")

        # Filter out return type and only process parameters
        param_type_hints = {
            name: type_hints.get(name)
            for name in sig.parameters
            if name != "return" and name not in ["agent", "team"]
        }

        # Parse docstring for parameters
        param_descriptions: Dict[str, Any] = {}
        if docstring := getdoc(c):
            parsed_doc = parse(docstring)
            param_docs = parsed_doc.params

            if param_docs is not None:
                for param in param_docs:
                    param_name = param.arg_name
                    param_type = param.type_name
                    if param_type is None:
                        param_descriptions[param_name] = param.description
                    else:
                        param_descriptions[param_name] = f"({param_type}) {param.description}"

        # Get JSON schema for parameters only
        parameters = get_json_schema(
            type_hints=param_type_hints, param_descriptions=param_descriptions, strict=strict
        )

        # If strict=True mark all fields as required
        # See: https://platform.openai.com/docs/guides/structured-outputs/supported-schemas#all-fields-must-be-required
        if strict:
            parameters["required"] = [name for name in parameters["properties"] if name not in ["agent", "team"]]
        else:
            # Mark a field as required if it has no default value (this would include optional fields)
            parameters["required"] = [
                name
                for name, param in sig.parameters.items()
                if param.default == param.empty and name != "self" and name not in ["agent", "team"]
            ]

        # log_debug(f"JSON schema for {function_name}: {parameters}")
    except Exception as e:
        log_warning(f"Could not parse args for {function_name}: {e}", exc_info=True)

    # Don't wrap async generator with validate_call
    if isasyncgenfunction(c):
        entrypoint = c
    else:
        entrypoint = validate_call(c, config=dict(arbitrary_types_allowed=True))  # type: ignore
    return cls(
        name=function_name,
        description=get_entrypoint_docstring(entrypoint=c),
        parameters=parameters,
        entrypoint=entrypoint,
    )

def process_entrypoint(self, strict: bool = False):
    """Process the entrypoint and make it ready for use by an agent."""
    from inspect import getdoc, isasyncgenfunction, signature

    from agno.utils.json_schema import get_json_schema

    if self.skip_entrypoint_processing:
        if strict:
            self.process_schema_for_strict()
        return

    if self.entrypoint is None:
        return

    parameters = {"type": "object", "properties": {}, "required": []}

    params_set_by_user = False
    # If the user set the parameters (i.e. they are different from the default), we should keep them
    if self.parameters != parameters:
        params_set_by_user = True

    try:
        sig = signature(self.entrypoint)
        type_hints = get_type_hints(self.entrypoint)

        # If function has an the agent argument, remove the agent parameter from the type hints
        if "agent" in sig.parameters:
            del type_hints["agent"]
        if "team" in sig.parameters:
            del type_hints["team"]
        # log_info(f"Type hints for {self.name}: {type_hints}")

        # Filter out return type and only process parameters
        param_type_hints = {
            name: type_hints.get(name)
            for name in sig.parameters
            if name != "return" and name not in ["agent", "team"]
        }

        # Parse docstring for parameters
        param_descriptions = {}
        if docstring := getdoc(self.entrypoint):
            parsed_doc = parse(docstring)
            param_docs = parsed_doc.params

            if param_docs is not None:
                for param in param_docs:
                    param_name = param.arg_name
                    param_type = param.type_name

                    # TODO: We should use type hints first, then map param types in docs to json schema types.
                    # This is temporary to not lose information
                    param_descriptions[param_name] = f"({param_type}) {param.description}"

        # Get JSON schema for parameters only
        parameters = get_json_schema(
            type_hints=param_type_hints, param_descriptions=param_descriptions, strict=strict
        )

        # If strict=True mark all fields as required
        # See: https://platform.openai.com/docs/guides/structured-outputs/supported-schemas#all-fields-must-be-required
        if strict:
            parameters["required"] = [name for name in parameters["properties"] if name not in ["agent", "team"]]
        else:
            # Mark a field as required if it has no default value
            parameters["required"] = [
                name
                for name, param in sig.parameters.items()
                if param.default == param.empty and name != "self" and name not in ["agent", "team"]
            ]

        if params_set_by_user:
            self.parameters["additionalProperties"] = False
            if strict:
                self.parameters["required"] = [
                    name for name in self.parameters["properties"] if name not in ["agent", "team"]
                ]
            else:
                # Mark a field as required if it has no default value
                self.parameters["required"] = [
                    name
                    for name, param in sig.parameters.items()
                    if param.default == param.empty and name != "self" and name not in ["agent", "team"]
                ]

        # log_debug(f"JSON schema for {self.name}: {parameters}")
    except Exception as e:
        log_warning(f"Could not parse args for {self.name}: {e}", exc_info=True)

    self.description = self.description or get_entrypoint_docstring(self.entrypoint)
    if not params_set_by_user:
        self.parameters = parameters

    try:
        # Don't wrap async generator with validate_call
        if not isasyncgenfunction(self.entrypoint):
            self.entrypoint = validate_call(self.entrypoint, config=dict(arbitrary_types_allowed=True))  # type: ignore
    except Exception as e:
        log_warning(f"Failed to add validate decorator to entrypoint: {e}")

class _FileDataNodeMixin:
    """Mixin class designed to handle file-based data nodes."""

    __EXTENSION_MAP = {"csv": "csv", "excel": "xlsx", "parquet": "parquet", "pickle": "p", "json": "json"}

    _DEFAULT_DATA_KEY = "default_data"
    _PATH_KEY = "path"
    _DEFAULT_PATH_KEY = "default_path"
    _IS_GENERATED_KEY = "is_generated"
    __TAIPY_DUPLICATE = "DUPLICATE_OF"

    __logger = _TaipyLogger._get_logger()

    def __init__(self, properties: Dict) -> None:
        self._path: str = properties.get(self._PATH_KEY, properties.get(self._DEFAULT_PATH_KEY))
        self._is_generated: bool = properties.get(self._IS_GENERATED_KEY, self._path is None)
        self._last_edit_date: Optional[datetime] = None

        if self._path and ".data" in self._path:
            self._path = self._migrate_path(self.storage_type(), self._path)  # type: ignore[attr-defined]
        if not self._path:
            self._path = self._build_path(self.storage_type())  # type: ignore[attr-defined]

        properties[self._IS_GENERATED_KEY] = self._is_generated
        properties[self._PATH_KEY] = self._path

    @property  # type: ignore
    @_self_reload(DataNode._MANAGER_NAME)
    def is_generated(self) -> bool:
        """Indicates if the file is generated."""
        return self._is_generated

    @property  # type: ignore
    @_self_reload(DataNode._MANAGER_NAME)
    def path(self) -> str:
        """The path to the file data of the data node."""
        return _normalize_path(self._path)

    @path.setter
    def path(self, value) -> None:
        _path = _normalize_path(value)
        self._path = _path
        self.properties[self._PATH_KEY] = _path  # type: ignore[attr-defined]
        self.properties[self._IS_GENERATED_KEY] = False  # type: ignore[attr-defined]

    def is_downloadable(self) -> ReasonCollection:
        """Check if the data node is downloadable.

        Returns:
            A `ReasonCollection^` object containing the reasons why the data node is not downloadable.
        """
        collection = ReasonCollection()
        if not os.path.exists(self.path):
            collection._add_reason(self.id, NoFileToDownload(self.path, self.id))  # type: ignore[attr-defined]
        elif not isfile(self.path):
            collection._add_reason(self.id, NotAFile(self.path, self.id))  # type: ignore[attr-defined]
        return collection

    def is_uploadable(self) -> ReasonCollection:
        """Check if the data node is upload-able.

        Returns:
            A `ReasonCollection^` object containing the reasons why the data node is not upload-able.
        """
        return ReasonCollection()

    def _get_downloadable_path(self) -> str:
        """Get the downloadable path of the file data of the data node.

        Returns:
            The downloadable path of the file data of the data node if it exists, otherwise an empty string.
        """
        if os.path.exists(self.path) and isfile(self._path):
            return self.path

        return ""

    def _upload(
        self,
        path: str,
        upload_checker: Optional[Callable[[str, Any], bool]] = None,
        editor_id: Optional[str] = None,
        comment: Optional[str] = None,
        **kwargs: Any,
    ) -> ReasonCollection:
        """Upload a file data to the data node.

        Arguments:
            path (str): The path of the file to upload to the data node.
            upload_checker (Optional[Callable[[str, Any], bool]]): A function to check if the
                upload is allowed. The function takes the title of the upload data and the data
                itself as arguments and returns True if the upload is allowed, otherwise False.
            editor_id (Optional[str]): The ID of the user who is uploading the file.
            comment (Optional[str]): A comment to add to the edit history of the data node.
            **kwargs: Additional keyword arguments. These arguments are stored in the edit
                history of the data node. In particular, an `editor_id` or a `comment` can be
                passed. The `editor_id` is the ID of the user who is uploading the file, and the
                `comment` is a comment to add to the edit history.

        Returns:
            True if the upload was successful, the reasons why the upload was not successful
            otherwise.
        """
        from ._data_manager_factory import _DataManagerFactory

        reasons = ReasonCollection()
        if (
            editor_id
            and self.edit_in_progress  # type: ignore[attr-defined]
            and self.editor_id != editor_id  # type: ignore[attr-defined]
            and (
                not self.editor_expiration_date  # type: ignore[attr-defined]
                or self.editor_expiration_date > datetime.now()  # type: ignore[attr-defined]
            )
        ):
            reasons._add_reason(self.id, DataNodeEditInProgress(self.id))  # type: ignore[attr-defined]
            return reasons

        up_path = pathlib.Path(path)
        try:
            upload_data = self._read_from_path(str(up_path))
        except Exception as err:
            self.__logger.error(f"Error uploading `{up_path.name}` to data " f"node `{self.id}`:")  # type: ignore[attr-defined]
            self.__logger.error(f"Error: {err}")
            reasons._add_reason(self.id, UploadFileCanNotBeRead(up_path.name, self.id))  # type: ignore[attr-defined]
            return reasons

        if upload_checker is not None:
            try:
                can_upload = upload_checker(up_path.name, upload_data)
            except Exception as err:
                self.__logger.error(
                    f"Error with the upload checker `{upload_checker.__name__}` "
                    f"while checking `{up_path.name}` file for upload to the data "
                    f"node `{self.id}`:"  # type: ignore[attr-defined]
                )
                self.__logger.error(f"Error: {err}")
                can_upload = False

            if not can_upload:
                reasons._add_reason(self.id, InvalidUploadFile(up_path.name, self.id))  # type: ignore[attr-defined]
                return reasons

        shutil.copy(up_path, self.path)

        self.track_edit(  # type: ignore[attr-defined]
            timestamp=datetime.now(),
            editor_id=editor_id,
            comment=comment,
            **kwargs,
        )
        self.unlock_edit()  # type: ignore[attr-defined]

        _DataManagerFactory._build_manager()._update(self)  # type: ignore[arg-type]

        return reasons

    def _read_from_path(self, path: Optional[str] = None, **read_kwargs) -> Any:
        raise NotImplementedError

    def _write_default_data(self, default_value: Any):
        if default_value is not None and not os.path.exists(self._path):
            self._write(default_value)  # type: ignore[attr-defined]
            self._last_edit_date = self._get_last_modified_datetime() or datetime.now()
            self._edits.append(  # type: ignore[attr-defined]
                Edit(
                    {
                        "timestamp": self._last_edit_date,
                        "editor": "TAIPY",
                        "comment": "Default data written.",
                    }
                )
            )

        if not self._last_edit_date and isfile(self._path):
            self._last_edit_date = datetime.now()

    def _get_last_modified_datetime(self) -> Optional[datetime]:
        if self._path and os.path.isfile(self._path):
            return datetime.fromtimestamp(os.path.getmtime(self._path))

        last_modified_datetime = None
        if self._path and os.path.isdir(self._path):
            for filename in os.listdir(self._path):
                filepath = os.path.join(self._path, filename)
                if os.path.isfile(filepath):
                    file_mtime = datetime.fromtimestamp(os.path.getmtime(filepath))

                    if last_modified_datetime is None or file_mtime > last_modified_datetime:
                        last_modified_datetime = file_mtime

        return last_modified_datetime

    def _build_path(self, storage_type) -> str:
        folder = f"{storage_type}s"
        dir_path = pathlib.Path(Config.core.storage_folder) / folder
        if not dir_path.exists():
            dir_path.mkdir(parents=True, exist_ok=True)
        return str(dir_path / f"{self.id}.{self.__EXTENSION_MAP.get(storage_type)}")  # type: ignore[attr-defined]

    def _migrate_path(self, storage_type, old_path) -> str:
        new_path = self._build_path(storage_type)
        if os.path.exists(old_path):
            shutil.move(old_path, new_path)
        return new_path

    def _duplicate_file(self, dest: DataNode):
        if os.path.exists(self._path):
            folder_path, base_name = os.path.split(self._path)
            new_path = os.path.join(folder_path, f"{dest.id}_{self.__TAIPY_DUPLICATE}_{base_name}")
            if os.path.isdir(self._path):
                shutil.copytree(self._path, new_path)
            else:
                shutil.copy(self._path, new_path)
            normalize_path = _normalize_path(new_path)
            dest._path = normalize_path
            dest._properties[self._PATH_KEY] = normalize_path

def _read_as(self, path: str):
    try:
        properties = self.properties
        excel_file = load_workbook(path, read_only=True)
        exposed_type = properties[self._EXPOSED_TYPE_PROPERTY]
        work_books = {}
        sheet_names = excel_file.sheetnames

        user_provided_sheet_names = properties.get(self.__SHEET_NAME_PROPERTY) or []
        if not isinstance(user_provided_sheet_names, (list, set, tuple)):
            user_provided_sheet_names = [user_provided_sheet_names]

        provided_sheet_names = user_provided_sheet_names or sheet_names

        for sheet_name in provided_sheet_names:
            if sheet_name not in sheet_names:
                raise NonExistingExcelSheet(sheet_name, path)

        if isinstance(exposed_type, List):
            if len(provided_sheet_names) != len(exposed_type):
                raise ExposedTypeLengthMismatch(
                    f"Expected {len(provided_sheet_names)} exposed types, got " f"{len(exposed_type)}"
                )

        for i, sheet_name in enumerate(provided_sheet_names):
            work_sheet = excel_file[sheet_name]
            sheet_exposed_type = exposed_type

            if not isinstance(sheet_exposed_type, str):
                if isinstance(exposed_type, dict):
                    sheet_exposed_type = exposed_type.get(sheet_name, self._EXPOSED_TYPE_PANDAS)
                elif isinstance(exposed_type, List):
                    sheet_exposed_type = exposed_type[i]
                elif exposed_type == np.ndarray:
                    sheet_exposed_type = self._EXPOSED_TYPE_NUMPY
                elif exposed_type == pd.DataFrame:
                    sheet_exposed_type = self._EXPOSED_TYPE_PANDAS

                if isinstance(sheet_exposed_type, str):
                    sheet_data = self._read_sheet_with_exposed_type(path, sheet_exposed_type, sheet_name)
                    if sheet_data is not None:
                        work_books[sheet_name] = sheet_data
                    continue

            res = [[col.value for col in row] for row in work_sheet.rows]
            if properties[self._HAS_HEADER_PROPERTY] and res:
                header = res.pop(0)
                for i, row in enumerate(res):
                    res[i] = sheet_exposed_type(**dict([[h, r] for h, r in zip(header, row)]))
            else:
                for i, row in enumerate(res):
                    res[i] = sheet_exposed_type(*row)
            work_books[sheet_name] = res  # type: ignore
    finally:
        excel_file.close()

    if len(user_provided_sheet_names) == 1:
        return work_books[user_provided_sheet_names[0]]

    return work_books

def __format_configs_parameter(clazz, parameter) -> List[str]:
    if isinstance(parameter, str):
        parameter = [parameter]
    if isinstance(parameter, clazz):
        parameter = [parameter.id]  # type: ignore[attr-defined]
    if isinstance(parameter, list):
        parameter = [cfg.id if isinstance(cfg, clazz) else cfg for cfg in parameter]  # type: ignore[attr-defined]
    return parameter

def __init__(self, **kwargs) -> None:
    from .custom import Page as CustomPage

    self._class_module_name = ""
    self._class_locals: t.Dict[str, t.Any] = {}
    self._frame: t.Optional[FrameType] = None
    page = self.create_page()
    if isinstance(page, str):
        from ._renderers import Markdown

        page = Markdown(page)
    self._renderer: t.Optional[Page] = page

    if "frame" in kwargs:
        self._frame = kwargs.get("frame")
    elif self._renderer:
        self._frame = self._renderer._frame
    elif isinstance(self, CustomPage):
        self._frame = t.cast(FrameType, t.cast(FrameType, inspect.stack()[2].frame))
        # Allow CustomPage class to be inherited
        if len(inspect.stack()) > 3 and inspect.stack()[2].function != "<module>":
            self._frame = t.cast(FrameType, t.cast(FrameType, inspect.stack()[3].frame))
    elif len(inspect.stack()) < 4:
        raise RuntimeError(f"Can't resolve module. Page '{type(self).__name__}' is not registered.")
    else:
        self._frame = t.cast(FrameType, t.cast(FrameType, inspect.stack()[3].frame))
    if self._renderer:
        # Extract the page module's attributes and methods
        cls = type(self)
        cls_locals = dict(vars(self))
        functions = [i[0] for i in inspect.getmembers(cls) if not i[0].startswith("_") and inspect.isroutine(i[1])]
        for f in functions:
            func = getattr(self, f)
            if hasattr(func, "__func__") and func.__func__ is not None:
                cls_locals[f] = func.__func__
        self._class_module_name = cls.__name__
        self._class_locals = cls_locals
    # Special variables only use for page reloading in notebook context
    self._notebook_gui: t.Optional["Gui"] = None
    self._notebook_page: t.Optional["_Page"] = None
    self.set_style(kwargs.get("style", None))
    self._script_paths(kwargs.get("script_paths", None))

def __init__(self, properties: Dict) -> None:
    self._path: str = properties.get(self._PATH_KEY, properties.get(self._DEFAULT_PATH_KEY))
    self._is_generated: bool = properties.get(self._IS_GENERATED_KEY, self._path is None)
    self._last_edit_date: Optional[datetime] = None

    if self._path and ".data" in self._path:
        self._path = self._migrate_path(self.storage_type(), self._path)  # type: ignore[attr-defined]
    if not self._path:
        self._path = self._build_path(self.storage_type())  # type: ignore[attr-defined]

    properties[self._IS_GENERATED_KEY] = self._is_generated
    properties[self._PATH_KEY] = self._path

