def _add_tools_to_model(self, model: Model, tools: List[Union[Function, Callable, Toolkit, Dict]]) -> None:
    # We have to reset for every run, because we will have new images/audio/video to attach
    _functions_for_model: Dict[str, Function] = {}
    _tools_for_model: List[Dict] = []

    # Get Agent tools
    if len(tools) > 0:
        log_debug("Processing tools for model")

        # Check if we need strict mode for the model
        strict = False
        if self.response_model is not None and not self.use_json_mode and model.supports_native_structured_outputs:
            strict = True

        for tool in tools:
            if isinstance(tool, Dict):
                # If a dict is passed, it is a builtin tool
                # that is run by the model provider and not the Agent
                _tools_for_model.append(tool)
                log_debug(f"Included builtin tool {tool}")

            elif isinstance(tool, Toolkit):
                # For each function in the toolkit and process entrypoint
                for name, func in tool.functions.items():
                    # If the function does not exist in self.functions
                    if name not in _functions_for_model:
                        func._agent = self
                        func._team = self
                        func.process_entrypoint(strict=strict)
                        if strict:
                            func.strict = True
                        if self.tool_hooks:
                            func.tool_hooks = self.tool_hooks
                        _functions_for_model[name] = func
                        _tools_for_model.append({"type": "function", "function": func.to_dict()})
                        log_debug(f"Added tool {name} from {tool.name}")

                # Add instructions from the toolkit
                if tool.add_instructions and tool.instructions is not None:
                    if self._tool_instructions is None:
                        self._tool_instructions = []
                    self._tool_instructions.append(tool.instructions)

            elif isinstance(tool, Function):
                if tool.name not in _functions_for_model:
                    tool._agent = self
                    tool._team = self
                    tool.process_entrypoint(strict=strict)
                    if strict and tool.strict is None:
                        tool.strict = True
                    if self.tool_hooks:
                        tool.tool_hooks = self.tool_hooks
                    _functions_for_model[tool.name] = tool
                    _tools_for_model.append({"type": "function", "function": tool.to_dict()})
                    log_debug(f"Added tool {tool.name}")

                # Add instructions from the Function
                if tool.add_instructions and tool.instructions is not None:
                    if self._tool_instructions is None:
                        self._tool_instructions = []
                    self._tool_instructions.append(tool.instructions)

            elif callable(tool):
                # We add the tools, which are callable functions
                try:
                    func = Function.from_callable(tool, strict=strict)
                    func._agent = self
                    func._team = self
                    if strict:
                        func.strict = True
                    if self.tool_hooks:
                        func.tool_hooks = self.tool_hooks
                    _functions_for_model[func.name] = func
                    _tools_for_model.append({"type": "function", "function": func.to_dict()})
                    log_debug(f"Added tool {func.name}")
                except Exception as e:
                    log_warning(f"Could not add tool {tool}: {e}")

        # Set tools on the model
        model.set_tools(tools=_tools_for_model)
        # Set functions on the model
        model.set_functions(functions=_functions_for_model)

def _create_run_data(self) -> Dict[str, Any]:
    """Create and return the run data dictionary."""
    run_response_format = "text"
    if self.response_model is not None:
        run_response_format = "json"
    elif self.markdown:
        run_response_format = "markdown"

    functions = {}
    if self.model is not None and self.model._functions is not None:
        functions = {
            f_name: func.to_dict() for f_name, func in self.model._functions.items() if isinstance(func, Function)
        }

    run_data: Dict[str, Any] = {
        "functions": functions,
        "metrics": self.run_response.metrics,  # type: ignore
    }

    if self.monitoring:
        run_data.update(
            {
                "run_input": self.run_input,
                "run_response": self.run_response.to_dict(),  # type: ignore
                "run_response_format": run_response_format,
            }
        )

    return run_data

def _get_team_session(self, session_id: str, user_id: Optional[str] = None) -> TeamSession:
    from time import time

    """Get an TeamMemory object, which can be saved to the database"""
    if self.memory is not None:
        if isinstance(self.memory, TeamMemory):
            self.memory = cast(TeamMemory, self.memory)
            memory_dict = self.memory.to_dict()
        else:
            self.memory = cast(Memory, self.memory)
            # We fake the structure on storage, to maintain the interface with the legacy implementation
            if self.memory.runs is not None:
                memory_dict = self.memory.to_dict()
                run_responses = self.memory.runs.get(session_id)
                if run_responses is not None:
                    memory_dict["runs"] = [rr.to_dict() for rr in run_responses]
    else:
        memory_dict = None

    return TeamSession(
        session_id=session_id,
        team_id=self.team_id,
        user_id=user_id,
        team_session_id=self.team_session_id,
        memory=memory_dict,
        team_data=self._get_team_data(),
        session_data=self._get_session_data(),
        extra_data=self.extra_data,
        created_at=int(time()),
    )

def prune_actor_input_schema(input_schema: Dict[str, Any]) -> Tuple[Dict[str, Any], List[str]]:
    """Get the input schema from the Actor build and trim descriptions.

    Args:
        input_schema (Dict[str, Any]): The input schema from the Actor build

    Returns:
        Tuple[Dict[str, Any], List[str]]: A tuple containing the pruned properties and required fields
    """
    properties = input_schema.get("properties", {})
    required = input_schema.get("required", [])

    properties_out: Dict[str, Any] = {}
    for item, meta in properties.items():
        properties_out[item] = {}
        if desc := meta.get("description"):
            properties_out[item]["description"] = (
                desc[:MAX_DESCRIPTION_LEN] + "..." if len(desc) > MAX_DESCRIPTION_LEN else desc
            )
        for key_name in ("type", "default", "prefill", "enum"):
            if value := meta.get(key_name):
                properties_out[item][key_name] = value

    return properties_out, required

def from_callable(cls, c: Callable, strict: bool = False) -> "Function":
    from inspect import getdoc, isasyncgenfunction, signature

    from agno.utils.json_schema import get_json_schema

    function_name = c.__name__
    parameters = {"type": "object", "properties": {}, "required": []}
    try:
        sig = signature(c)
        type_hints = get_type_hints(c)

        # If function has an the agent argument, remove the agent parameter from the type hints
        if "agent" in sig.parameters:
            del type_hints["agent"]
        if "team" in sig.parameters:
            del type_hints["team"]
        # log_info(f"Type hints for {function_name}: {type_hints}")

        # Filter out return type and only process parameters
        param_type_hints = {
            name: type_hints.get(name)
            for name in sig.parameters
            if name != "return" and name not in ["agent", "team"]
        }

        # Parse docstring for parameters
        param_descriptions: Dict[str, Any] = {}
        if docstring := getdoc(c):
            parsed_doc = parse(docstring)
            param_docs = parsed_doc.params

            if param_docs is not None:
                for param in param_docs:
                    param_name = param.arg_name
                    param_type = param.type_name
                    if param_type is None:
                        param_descriptions[param_name] = param.description
                    else:
                        param_descriptions[param_name] = f"({param_type}) {param.description}"

        # Get JSON schema for parameters only
        parameters = get_json_schema(
            type_hints=param_type_hints, param_descriptions=param_descriptions, strict=strict
        )

        # If strict=True mark all fields as required
        # See: https://platform.openai.com/docs/guides/structured-outputs/supported-schemas#all-fields-must-be-required
        if strict:
            parameters["required"] = [name for name in parameters["properties"] if name not in ["agent", "team"]]
        else:
            # Mark a field as required if it has no default value
            parameters["required"] = [
                name
                for name, param in sig.parameters.items()
                if param.default == param.empty and name != "self" and name not in ["agent", "team"]
            ]

        # log_debug(f"JSON schema for {function_name}: {parameters}")
    except Exception as e:
        log_warning(f"Could not parse args for {function_name}: {e}", exc_info=True)

    # Don't wrap async generator with validate_call
    if isasyncgenfunction(c):
        entrypoint = c
    else:
        entrypoint = validate_call(c, config=dict(arbitrary_types_allowed=True))  # type: ignore
    return cls(
        name=function_name,
        description=get_entrypoint_docstring(entrypoint=c),
        parameters=parameters,
        entrypoint=entrypoint,
    )

def process_entrypoint(self, strict: bool = False):
    """Process the entrypoint and make it ready for use by an agent."""
    from inspect import getdoc, isasyncgenfunction, signature

    from agno.utils.json_schema import get_json_schema

    if self.skip_entrypoint_processing:
        if strict:
            self.process_schema_for_strict()
        return

    if self.entrypoint is None:
        return

    parameters = {"type": "object", "properties": {}, "required": []}

    params_set_by_user = False
    # If the user set the parameters (i.e. they are different from the default), we should keep them
    if self.parameters != parameters:
        params_set_by_user = True

    try:
        sig = signature(self.entrypoint)
        type_hints = get_type_hints(self.entrypoint)

        # If function has an the agent argument, remove the agent parameter from the type hints
        if "agent" in sig.parameters:
            del type_hints["agent"]
        if "team" in sig.parameters:
            del type_hints["team"]
        # log_info(f"Type hints for {self.name}: {type_hints}")

        # Filter out return type and only process parameters
        param_type_hints = {
            name: type_hints.get(name)
            for name in sig.parameters
            if name != "return" and name not in ["agent", "team"]
        }

        # Parse docstring for parameters
        param_descriptions = {}
        if docstring := getdoc(self.entrypoint):
            parsed_doc = parse(docstring)
            param_docs = parsed_doc.params

            if param_docs is not None:
                for param in param_docs:
                    param_name = param.arg_name
                    param_type = param.type_name

                    # TODO: We should use type hints first, then map param types in docs to json schema types.
                    # This is temporary to not lose information
                    param_descriptions[param_name] = f"({param_type}) {param.description}"

        # Get JSON schema for parameters only
        parameters = get_json_schema(
            type_hints=param_type_hints, param_descriptions=param_descriptions, strict=strict
        )

        # If strict=True mark all fields as required
        # See: https://platform.openai.com/docs/guides/structured-outputs/supported-schemas#all-fields-must-be-required
        if strict:
            parameters["required"] = [name for name in parameters["properties"] if name not in ["agent", "team"]]
        else:
            # Mark a field as required if it has no default value
            parameters["required"] = [
                name
                for name, param in sig.parameters.items()
                if param.default == param.empty and name != "self" and name not in ["agent", "team"]
            ]

        if params_set_by_user:
            self.parameters["additionalProperties"] = False
            if strict:
                self.parameters["required"] = [
                    name for name in self.parameters["properties"] if name not in ["agent", "team"]
                ]
            else:
                # Mark a field as required if it has no default value
                self.parameters["required"] = [
                    name
                    for name, param in sig.parameters.items()
                    if param.default == param.empty and name != "self" and name not in ["agent", "team"]
                ]

        # log_debug(f"JSON schema for {self.name}: {parameters}")
    except Exception as e:
        log_warning(f"Could not parse args for {self.name}: {e}", exc_info=True)

    self.description = self.description or get_entrypoint_docstring(self.entrypoint)
    if not params_set_by_user:
        self.parameters = parameters

    try:
        # Don't wrap async generator with validate_call
        if not isasyncgenfunction(self.entrypoint):
            self.entrypoint = validate_call(self.entrypoint, config=dict(arbitrary_types_allowed=True))  # type: ignore
    except Exception as e:
        log_warning(f"Failed to add validate decorator to entrypoint: {e}")

class TeamMemberInteraction:
    member_name: str
    task: str
    response: Union[RunResponse, TeamRunResponse]

    def to_dict(self) -> Dict[str, Any]:
        return {
            "member_name": self.member_name,
            "task": self.task,
            "response": self.response.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "TeamMemberInteraction":
        return cls(member_name=data["member_name"], task=data["task"], response=RunResponse.from_dict(data["response"]))

class TeamContext:
    # List of team member interaction, represented as a request and a response
    member_interactions: List[TeamMemberInteraction] = field(default_factory=list)
    text: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return {
            "member_interactions": [interaction.to_dict() for interaction in self.member_interactions],
            "text": self.text,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "TeamContext":
        return cls(
            member_interactions=[
                TeamMemberInteraction.from_dict(interaction) for interaction in data["member_interactions"]
            ],
            text=data["text"],
        )

def get_model(self) -> Model:
    if self.model is None:
        try:
            from agno.models.openai import OpenAIChat
        except ModuleNotFoundError as e:
            logger.exception(e)
            logger.error(
                "Agno uses `openai` as the default model provider. Please provide a `model` or install `openai`."
            )
            exit(1)
        self.model = OpenAIChat(id="gpt-4o")
    return self.model

def _format_file_for_message(self, file: File) -> Optional[Part]:
    # Case 1: File is a bytes object
    if file.content and isinstance(file.content, bytes):
        return Part.from_bytes(mime_type=file.mime_type, data=file.content)

    # Case 2: File is a URL
    elif file.url is not None:
        url_content = file.file_url_content
        if url_content is not None:
            content, mime_type = url_content
            return Part.from_bytes(mime_type=mime_type, data=content)
        else:
            log_warning(f"Failed to download file from {file.url}")
            return None

    # Case 3: File is a local file path
    elif file.filepath is not None:
        file_path = file.filepath if isinstance(file.filepath, Path) else Path(file.filepath)
        if file_path.exists() and file_path.is_file():
            if file_path.stat().st_size < 20 * 1024 * 1024:  # 20MB in bytes
                if file.mime_type is not None:
                    return Part.from_bytes(mime_type=file.mime_type, data=file_path.read_bytes())
                else:
                    import mimetypes

                    return Part.from_bytes(
                        mime_type=mimetypes.guess_type(file_path)[0], data=file_path.read_bytes()
                    )
            else:
                clean_file_name = f"files/{file_path.stem.lower().replace('_', '')}"
                remote_file = None
                try:
                    remote_file = self.get_client().files.get(name=clean_file_name)
                except Exception as e:
                    log_warning(f"Error getting file {clean_file_name}: {e}")

                if remote_file is not None:
                    return Part.from_uri(file_uri=remote_file.uri, mime_type=remote_file.mime_type)
                else:
                    file_upload = self.get_client().files.upload(
                        file=file_path,
                        config=dict(
                            name=clean_file_name,
                        ),
                    )
                    # Check whether the file is ready to be used.
                    while file_upload.state.name == "PROCESSING":
                        time.sleep(2)
                        file_upload = self.get_client().files.get(name=file_upload.name)
                    if file_upload.state.name == "FAILED":
                        raise ValueError(file_upload.state.name)
                    return Part.from_uri(file_uri=file_upload.uri, mime_type=file_upload.mime_type)
        else:
            log_error(f"File {file_path} does not exist.")

    # Case 4: File is a Gemini File object
    elif isinstance(file.external, GeminiFile):
        return file.external
    return None

def _run(
    self,
    run_response: TeamRunResponse,
    run_messages: RunMessages,
    session_id: str,
    user_id: Optional[str] = None,
) -> None:
    """Run the Team and return the response.

    Steps:
    1. Reason about the task(s) if reasoning is enabled
    2. Get a response from the model
    3. Update the run_response
    4. Update Team Memory
    5. Calculate session metrics
    6. Save session to storage
    7. Parse any structured outputs
    8. Log the team run
    """
    if isinstance(self.memory, TeamMemory):
        self.memory = cast(TeamMemory, self.memory)
    else:
        self.memory = cast(Memory, self.memory)
    self.model = cast(Model, self.model)

    # 1. Reason about the task(s) if reasoning is enabled
    if self.reasoning or self.reasoning_model is not None:
        reasoning_generator = self._reason(
            run_response=run_response, run_messages=run_messages, session_id=session_id
        )

        # Consume the generator without yielding
        deque(reasoning_generator, maxlen=0)

    # Update agent state
    self.run_messages = run_messages
    index_of_last_user_message = len(run_messages.messages)

    # 2. Get the model response for the team leader
    model_response = self.model.response(messages=run_messages.messages)  # type: ignore

    # 3. Update TeamRunResponse
    # Handle structured outputs
    if (self.response_model is not None) and not self.use_json_mode and (model_response.parsed is not None):
        # Update the run_response content with the structured output
        run_response.content = model_response.parsed
        # Update the run_response content_type with the structured output class name
        run_response.content_type = self.response_model.__name__
    else:
        # Update the run_response content with the model response content
        if not run_response.content:
            run_response.content = model_response.content
        else:
            run_response.content += model_response.content

    # Update the run_response thinking with the model response thinking
    if model_response.thinking is not None:
        if not run_response.thinking:
            run_response.thinking = model_response.thinking
        else:
            run_response.thinking += model_response.thinking

    # Update citations
    if model_response.citations is not None:
        run_response.citations = model_response.citations

    # Update the run_response tools with the model response tools
    if model_response.tool_calls is not None:
        if run_response.tools is None:
            run_response.tools = model_response.tool_calls
        else:
            run_response.tools.extend(model_response.tool_calls)

    run_response.formatted_tool_calls = format_tool_calls(run_response.tools)

    # Update the run_response audio with the model response audio
    if model_response.audio is not None:
        run_response.response_audio = model_response.audio

    # Update the run_response created_at with the model response created_at
    run_response.created_at = model_response.created_at

    # Build a list of messages that should be added to the RunResponse
    messages_for_run_response = [m for m in run_messages.messages if m.add_to_agent_memory]

    # Update the TeamRunResponse messages
    run_response.messages = messages_for_run_response

    # Update the TeamRunResponse metrics
    run_response.metrics = self._aggregate_metrics_from_messages(messages_for_run_response)

    for tool_call in model_response.tool_calls:
        tool_name = tool_call.get("tool_name", "")
        if tool_name.lower() in ["think", "analyze"]:
            tool_args = tool_call.get("tool_args", {})
            self.update_reasoning_content_from_tool_call(run_response, tool_name, tool_args)

    # 4. Update Team Memory
    if isinstance(self.memory, TeamMemory):
        # Add the system message to the memory
        if run_messages.system_message is not None:
            self.memory.add_system_message(run_messages.system_message, system_message_role="system")  # type: ignore

        # Build a list of messages that should be added to the TeamMemory
        messages_for_memory: List[Message] = (
            [run_messages.user_message] if run_messages.user_message is not None else []
        )

        for _rm in run_messages.messages[index_of_last_user_message:]:
            if _rm.add_to_agent_memory:
                messages_for_memory.append(_rm)
        if len(messages_for_memory) > 0:
            self.memory.add_messages(messages=messages_for_memory)  # type: ignore

        team_run = TeamRun(response=run_response)
        team_run.message = run_messages.user_message

        # Update the memories with the user message if needed
        if (
            self.memory is not None
            and self.memory.create_user_memories
            and self.memory.update_user_memories_after_run
            and run_messages.user_message is not None
        ):
            self.memory.update_memory(input=run_messages.user_message.get_content_string())  # type: ignore

        # Add AgentRun to memory
        self.memory.add_team_run(team_run)  # type: ignore
        self.session_metrics = self._calculate_session_metrics(self.memory.messages)
        self.full_team_session_metrics = self._calculate_full_team_session_metrics(self.memory.messages, session_id)
    elif isinstance(self.memory, Memory):
        self.memory.add_run(session_id, run_response)

        self._make_memories_and_summaries(run_messages, session_id, user_id)

        session_messages: List[Message] = []
        for run in self.memory.runs.get(session_id, []):  # type: ignore
            if run.messages is not None:
                for m in run.messages:
                    session_messages.append(m)

        # 10. Calculate session metrics
        self.session_metrics = self._calculate_session_metrics(session_messages)

    # 6. Save session to storage
    self.write_to_storage(session_id=session_id, user_id=user_id)

    # 7. Parse team response model
    if self.response_model is not None and not isinstance(run_response.content, self.response_model):
        if isinstance(run_response.content, str) and self.parse_response:
            try:
                parsed_response_content = parse_response_model_str(run_response.content, self.response_model)

                # Update TeamRunResponse
                if parsed_response_content is not None:
                    run_response.content = parsed_response_content
                    run_response.content_type = self.response_model.__name__
                else:
                    log_warning("Failed to convert response to response_model")
            except Exception as e:
                log_warning(f"Failed to convert response to output model: {e}")
        else:
            log_warning("Something went wrong. Team run response content is not a string")
    elif self._member_response_model is not None and not isinstance(
        run_response.content, self._member_response_model
    ):
        if isinstance(run_response.content, str):
            try:
                parsed_response_content = parse_response_model_str(
                    run_response.content, self._member_response_model
                )
                # Update TeamRunResponse
                if parsed_response_content is not None:
                    run_response.content = parsed_response_content
                    run_response.content_type = self._member_response_model.__name__
                else:
                    log_warning("Failed to convert response to response_model")
            except Exception as e:
                log_warning(f"Failed to convert response to output model: {e}")
        else:
            log_warning("Something went wrong. Member run response content is not a string")

    # 8. Log Team Run
    self._log_team_run(session_id=session_id, user_id=user_id)

    log_debug(f"Team Run End: {self.run_id}", center=True, symbol="*")

def _add_tools_to_model(self, model: Model, tools: List[Union[Function, Callable, Toolkit, Dict]]) -> None:
    # We have to reset for every run, because we will have new images/audio/video to attach
    _functions_for_model: Dict[str, Function] = {}
    _tools_for_model: List[Dict] = []

    # Get Agent tools
    if len(tools) > 0:
        log_debug("Processing tools for model")

        # Check if we need strict mode for the model
        strict = False
        if self.response_model is not None and not self.use_json_mode and model.supports_native_structured_outputs:
            strict = True

        for tool in tools:
            if isinstance(tool, Dict):
                # If a dict is passed, it is a builtin tool
                # that is run by the model provider and not the Agent
                _tools_for_model.append(tool)
                log_debug(f"Included builtin tool {tool}")

            elif isinstance(tool, Toolkit):
                # For each function in the toolkit and process entrypoint
                for name, func in tool.functions.items():
                    # If the function does not exist in self.functions
                    if name not in _functions_for_model:
                        func._agent = self
                        func._team = self
                        func.process_entrypoint(strict=strict)
                        if strict:
                            func.strict = True
                        if self.tool_hooks:
                            func.tool_hooks = self.tool_hooks
                        _functions_for_model[name] = func
                        _tools_for_model.append({"type": "function", "function": func.to_dict()})
                        log_debug(f"Added tool {name} from {tool.name}")

                # Add instructions from the toolkit
                if tool.add_instructions and tool.instructions is not None:
                    if self._tool_instructions is None:
                        self._tool_instructions = []
                    self._tool_instructions.append(tool.instructions)

            elif isinstance(tool, Function):
                if tool.name not in _functions_for_model:
                    tool._agent = self
                    tool._team = self
                    tool.process_entrypoint(strict=strict)
                    if strict and tool.strict is None:
                        tool.strict = True
                    if self.tool_hooks:
                        tool.tool_hooks = self.tool_hooks
                    _functions_for_model[tool.name] = tool
                    _tools_for_model.append({"type": "function", "function": tool.to_dict()})
                    log_debug(f"Added tool {tool.name}")

                # Add instructions from the Function
                if tool.add_instructions and tool.instructions is not None:
                    if self._tool_instructions is None:
                        self._tool_instructions = []
                    self._tool_instructions.append(tool.instructions)

            elif callable(tool):
                # We add the tools, which are callable functions
                try:
                    func = Function.from_callable(tool, strict=strict)
                    func._agent = self
                    func._team = self
                    if strict:
                        func.strict = True
                    if self.tool_hooks:
                        func.tool_hooks = self.tool_hooks
                    _functions_for_model[func.name] = func
                    _tools_for_model.append({"type": "function", "function": func.to_dict()})
                    log_debug(f"Added tool {func.name}")
                except Exception as e:
                    log_warning(f"Could not add tool {tool}: {e}")

        # Set tools on the model
        model.set_tools(tools=_tools_for_model)
        # Set functions on the model
        model.set_functions(functions=_functions_for_model)

def _get_json_output_prompt(self) -> str:
    """Return the JSON output prompt for the Agent.

    This is added to the system prompt when the response_model is set and structured_outputs is False.
    """
    import json

    json_output_prompt = "Provide your output as a JSON containing the following fields:"
    if self.response_model is not None:
        if isinstance(self.response_model, str):
            json_output_prompt += "\n<json_fields>"
            json_output_prompt += f"\n{self.response_model}"
            json_output_prompt += "\n</json_fields>"
        elif isinstance(self.response_model, list):
            json_output_prompt += "\n<json_fields>"
            json_output_prompt += f"\n{json.dumps(self.response_model)}"
            json_output_prompt += "\n</json_fields>"
        elif issubclass(self.response_model, BaseModel):
            json_schema = self.response_model.model_json_schema()
            if json_schema is not None:
                response_model_properties = {}
                json_schema_properties = json_schema.get("properties")
                if json_schema_properties is not None:
                    for field_name, field_properties in json_schema_properties.items():
                        formatted_field_properties = {
                            prop_name: prop_value
                            for prop_name, prop_value in field_properties.items()
                            if prop_name != "title"
                        }
                        response_model_properties[field_name] = formatted_field_properties
                json_schema_defs = json_schema.get("$defs")
                if json_schema_defs is not None:
                    response_model_properties["$defs"] = {}
                    for def_name, def_properties in json_schema_defs.items():
                        def_fields = def_properties.get("properties")
                        formatted_def_properties = {}
                        if def_fields is not None:
                            for field_name, field_properties in def_fields.items():
                                formatted_field_properties = {
                                    prop_name: prop_value
                                    for prop_name, prop_value in field_properties.items()
                                    if prop_name != "title"
                                }
                                formatted_def_properties[field_name] = formatted_field_properties
                        if len(formatted_def_properties) > 0:
                            response_model_properties["$defs"][def_name] = formatted_def_properties

                if len(response_model_properties) > 0:
                    json_output_prompt += "\n<json_fields>"
                    json_output_prompt += (
                        f"\n{json.dumps([key for key in response_model_properties.keys() if key != '$defs'])}"
                    )
                    json_output_prompt += "\n</json_fields>"
                    json_output_prompt += "\n\nHere are the properties for each field:"
                    json_output_prompt += "\n<json_field_properties>"
                    json_output_prompt += f"\n{json.dumps(response_model_properties, indent=2)}"
                    json_output_prompt += "\n</json_field_properties>"
        else:
            log_warning(f"Could not build json schema for {self.response_model}")
    else:
        json_output_prompt += "Provide the output as JSON."

    json_output_prompt += "\nStart your response with `{` and end it with `}`."
    json_output_prompt += "\nYour output will be passed to json.loads() to convert it to a Python object."
    json_output_prompt += "\nMake sure it only contains valid JSON."
    return json_output_prompt

def _convert_context_to_string(self, context: Dict[str, Any]) -> str:
    """Convert the context dictionary to a string representation.

    Args:
        context: Dictionary containing context data

    Returns:
        String representation of the context, or empty string if conversion fails
    """

    if context is None:
        return ""

    import json

    try:
        return json.dumps(context, indent=2, default=str)
    except (TypeError, ValueError, OverflowError) as e:
        log_warning(f"Failed to convert context to JSON: {e}")
        # Attempt a fallback conversion for non-serializable objects
        sanitized_context = {}
        for key, value in context.items():
            try:
                # Try to serialize each value individually
                json.dumps({key: value}, default=str)
                sanitized_context[key] = value
            except Exception as e:
                log_error(f"Failed to serialize to JSON: {e}")
                # If serialization fails, convert to string representation
                sanitized_context[key] = str(value)

        try:
            return json.dumps(sanitized_context, indent=2)
        except Exception as e:
            log_error(f"Failed to convert sanitized context to JSON: {e}")
            return str(context)

def prune_actor_input_schema(input_schema: Dict[str, Any]) -> Tuple[Dict[str, Any], List[str]]:
    """Get the input schema from the Actor build and trim descriptions.

    Args:
        input_schema (Dict[str, Any]): The input schema from the Actor build

    Returns:
        Tuple[Dict[str, Any], List[str]]: A tuple containing the pruned properties and required fields
    """
    properties = input_schema.get("properties", {})
    required = input_schema.get("required", [])

    properties_out: Dict[str, Any] = {}
    for item, meta in properties.items():
        properties_out[item] = {}
        if desc := meta.get("description"):
            properties_out[item]["description"] = (
                desc[:MAX_DESCRIPTION_LEN] + "..." if len(desc) > MAX_DESCRIPTION_LEN else desc
            )
        for key_name in ("type", "default", "prefill", "enum"):
            if value := meta.get(key_name):
                properties_out[item][key_name] = value

    return properties_out, required

