def test_call_list_append(self):
    def testfunc(n):
        a = []
        for i in range(n):
            a.append(i)
        return sum(a)

    res, ex = self._run_with_optimizer(testfunc, TIER2_THRESHOLD)
    self.assertEqual(res, sum(range(TIER2_THRESHOLD)))
    uops = get_opnames(ex)
    self.assertIn("_CALL_LIST_APPEND", uops)
