def merge_locustfiles_content(
    locustfiles: list[str],
) -> tuple[
    dict[str, type[locust.User]],
    dict[str, locust.LoadTestShape],
    dict[str, list[locust.TaskSet | Callable]],
    locust.LoadTestShape | None,
]:
    """
    Validate content of each locustfile in locustfiles and merge data to single objects output.

    Can stop locust execution on errors.
    """
    available_user_classes: dict[str, type[locust.User]] = {}
    available_shape_classes: dict[str, locust.LoadTestShape] = {}
    # TODO: list[locust.TaskSet | Callable] should be replaced with correct type,
    #  supported by User class task attribute. This require additional rewrite,
    #  out of main refactoring.
    #  Check docs for real supported task attribute signature for User\TaskSet class.
    available_user_tasks: dict[str, list[locust.TaskSet | Callable]] = {}

    def set_available_things(user_classes, shape_classes):
        # Setting Available Shape Classes
        for _shape_class in shape_classes:
            shape_class_name = type(_shape_class).__name__
            if shape_class_name in available_shape_classes.keys():
                sys.stderr.write(f"Duplicate shape classes: {shape_class_name}\n")
                sys.exit(1)

            available_shape_classes[shape_class_name] = _shape_class

        # Setting Available User Classes
        for class_name, class_definition in user_classes.items():
            if class_name in available_user_classes.keys():
                previous_path = inspect.getfile(available_user_classes[class_name])
                new_path = inspect.getfile(class_definition)
                if previous_path == new_path:
                    # The same User class was defined in two locustfiles but one probably imported the other, so we just ignore it
                    continue
                else:
                    sys.stderr.write(
                        f"Duplicate user class names: {class_name} is defined in both {previous_path} and {new_path}\n"
                    )
                    sys.exit(1)

            available_user_classes[class_name] = class_definition
            available_user_tasks[class_name] = class_definition.tasks

    for _locustfile in locustfiles:
        user_classes, shape_classes = load_locustfile(_locustfile)
        set_available_things(user_classes, shape_classes)

    if not available_user_classes:  # only load pytest-based locustfiles if no regular ones were found
        for _locustfile in locustfiles:
            user_classes = load_locustfile_pytest(_locustfile)
            set_available_things(user_classes, [])

    shape_class = list(available_shape_classes.values())[0] if available_shape_classes else None

    return available_user_classes, available_shape_classes, available_user_tasks, shape_class

def get_html_report(
    environment,
    show_download_link=True,
    theme="",
):
    request_stats = environment.runner.stats

    start_time = format_utc_timestamp(request_stats.start_time)

    if end_ts := request_stats.last_request_timestamp:
        end_time = format_utc_timestamp(end_ts)
    else:
        end_ts = request_stats.start_time
        end_time = start_time

    host = None
    if environment.host:
        host = environment.host
    elif environment.runner.user_classes:
        all_hosts = {l.host for l in environment.runner.user_classes}
        if len(all_hosts) == 1:
            host = list(all_hosts)[0]

    requests_statistics = list(chain(stats.sort_stats(request_stats.entries), [request_stats.total]))
    failures_statistics = stats.sort_stats(request_stats.errors)
    exceptions_statistics = [
        {**exc, "nodes": ", ".join(exc["nodes"])} for exc in environment.runner.exceptions.values()
    ]

    if request_stats.history and request_stats.history[-1]["time"] < end_time:
        stats.update_stats_history(environment.runner, end_time)
    history = request_stats.history

    is_distributed = isinstance(environment.runner, MasterRunner)
    user_spawned = (
        environment.runner.reported_user_classes_count if is_distributed else environment.runner.user_classes_count
    )

    if environment.runner.state in [STATE_STOPPED, STATE_STOPPING]:
        user_spawned = environment.runner.final_user_classes_count

    task_data = {
        "per_class": get_ratio(environment.user_classes, user_spawned, False),
        "total": get_ratio(environment.user_classes, user_spawned, True),
    }

    return render_template_from(
        "report.html",
        template_args={
            "is_report": True,
            "requests_statistics": [stat.to_dict() for stat in requests_statistics],
            "failures_statistics": [stat.to_dict() for stat in failures_statistics],
            "exceptions_statistics": [stat for stat in exceptions_statistics],
            "response_time_statistics": [
                {
                    "name": stat.name,
                    "method": stat.method or "",
                    **{
                        str(percentile): stat.get_response_time_percentile(percentile)
                        for percentile in PERCENTILES_FOR_HTML_REPORT
                    },
                }
                for stat in requests_statistics
            ],
            "start_time": start_time,
            "end_time": end_time,
            "duration": format_duration(request_stats.start_time, end_ts),
            "host": str(host),
            "history": history,
            "show_download_link": show_download_link,
            "locustfile": str(environment.locustfile),
            "tasks": task_data,
            "percentiles_to_chart": stats.PERCENTILES_TO_CHART,
            "profile": str(environment.profile) if environment.profile else None,
        },
        theme="dark" if theme == "dark" else "light",
    )

class FlaskDashServer(BaseDashServer):
    def __init__(self, server: Flask) -> None:
        self.server: Flask = server
        self.server_type = "flask"
        super().__init__()

    def __call__(self, *args: Any, **kwargs: Any):
        # Always WSGI
        return self.server(*args, **kwargs)

    @staticmethod
    def create_app(name: str = "__main__", config: Dict[str, Any] | None = None):
        app = Flask(name)
        if config:
            app.config.update(config)
        return app

    def register_assets_blueprint(
        self, blueprint_name: str, assets_url_path: str, assets_folder: str
    ):
        bp = Blueprint(
            blueprint_name,
            __name__,
            static_folder=assets_folder,
            static_url_path=assets_url_path,
        )
        self.server.register_blueprint(bp)

    def register_error_handlers(self):
        @self.server.errorhandler(PreventUpdate)
        def _handle_error(_):
            return "", 204

        @self.server.errorhandler(InvalidResourceError)
        def _invalid_resources_handler(err):
            return err.args[0], 404

    def _get_traceback(self, secret, error: Exception):
        try:
            from werkzeug.debug import (
                tbtools,
            )  # pylint: disable=import-outside-toplevel
        except ImportError:
            tbtools = None

        def _get_skip(error):
            tb = error.__traceback__
            skip = 1
            while tb.tb_next is not None:
                skip += 1
                tb = tb.tb_next
                if tb.tb_frame.f_code in [
                    _invoke_callback.__code__,
                    _async_invoke_callback.__code__,
                ]:
                    return skip
            return skip

        def _do_skip(error):
            tb = error.__traceback__
            while tb.tb_next is not None:
                if tb.tb_frame.f_code in [
                    _invoke_callback.__code__,
                    _async_invoke_callback.__code__,
                ]:
                    return tb.tb_next
                tb = tb.tb_next
            return error.__traceback__

        if hasattr(tbtools, "get_current_traceback"):
            return tbtools.get_current_traceback(skip=_get_skip(error)).render_full()
        if hasattr(tbtools, "DebugTraceback"):
            return tbtools.DebugTraceback(
                error, skip=_get_skip(error)
            ).render_debugger_html(True, secret, True)
        return "".join(traceback.format_exception(type(error), error, _do_skip(error)))

    def register_prune_error_handler(self, secret, prune_errors):
        if prune_errors:

            @self.server.errorhandler(Exception)
            def _wrap_errors(error):
                tb = self._get_traceback(secret, error)
                return tb, 500

    def add_url_rule(
        self,
        rule: str,
        view_func: Callable[..., Any],
        endpoint: str | None = None,
        methods: list[str] | None = None,
    ):
        self.server.add_url_rule(
            rule, view_func=view_func, endpoint=endpoint, methods=methods or ["GET"]
        )

    def before_request(self, func: Callable[[], Any]):
        # Flask expects a callable; user responsibility not to pass None
        self.server.before_request(func)

    def after_request(self, func: Callable[[Any], Any]):
        # Flask after_request expects a function(response) -> response
        self.server.after_request(func)

    def run(self, dash_app: Dash, host: str, port: int, debug: bool, **kwargs: Any):
        self.server.run(host=host, port=port, debug=debug, **kwargs)

    def make_response(
        self,
        data: str | bytes | bytearray,
        mimetype: str | None = None,
        content_type: str | None = None,
    ):
        return Response(data, mimetype=mimetype, content_type=content_type)

    def jsonify(self, obj: Any):
        return jsonify(obj)

    def setup_catchall(self, dash_app: Dash):
        def catchall(*args, **kwargs):
            return dash_app.index(*args, **kwargs)

        # pylint: disable=protected-access
        dash_app._add_url("<path:path>", catchall, methods=["GET"])

    def setup_index(self, dash_app: Dash):
        def index(*args, **kwargs):
            return dash_app.index(*args, **kwargs)

        # pylint: disable=protected-access
        dash_app._add_url("", index, methods=["GET"])

    def serve_component_suites(
        self, dash_app: Dash, package_name: str, fingerprinted_path: str
    ):
        path_in_pkg, has_fingerprint = check_fingerprint(fingerprinted_path)
        _validate.validate_js_path(dash_app.registered_paths, package_name, path_in_pkg)
        extension = "." + path_in_pkg.split(".")[-1]
        mimetype = mimetypes.types_map.get(extension, "application/octet-stream")
        package = sys.modules[package_name]
        dash_app.logger.debug(
            "serving -- package: %s[%s] resource: %s => location: %s",
            package_name,
            package.__version__,
            path_in_pkg,
            package.__path__,
        )
        data = pkgutil.get_data(package_name, path_in_pkg)
        response = Response(data, mimetype=mimetype)
        if has_fingerprint:
            response.cache_control.max_age = 31536000  # 1 year
        else:
            response.add_etag()
            tag = response.get_etag()[0]
            request_etag = request.headers.get("If-None-Match")
            if f'"{tag}"' == request_etag:
                response = Response(None, status=304)
        return response

    def setup_component_suites(self, dash_app: Dash):
        def serve(package_name, fingerprinted_path):
            return self.serve_component_suites(
                dash_app, package_name, fingerprinted_path
            )

        # pylint: disable=protected-access
        dash_app._add_url(
            "_dash-component-suites/<string:package_name>/<path:fingerprinted_path>",
            serve,
        )

    # pylint: disable=unused-argument
    def dispatch(self, dash_app: Dash):
        def _dispatch():
            body = request.get_json()
            # pylint: disable=protected-access
            cb_ctx = dash_app._initialize_context(body)
            func = dash_app._prepare_callback(cb_ctx, body)
            args = dash_app._inputs_to_vals(cb_ctx.inputs_list + cb_ctx.states_list)
            ctx = copy_context()
            partial_func = dash_app._execute_callback(
                func, args, cb_ctx.outputs_list, cb_ctx
            )
            response_data = ctx.run(partial_func)
            if asyncio.iscoroutine(response_data):
                raise Exception(
                    "You are trying to use a coroutine without dash[async]. "
                    "Please install the dependencies via `pip install dash[async]` and ensure "
                    "that `use_async=False` is not being passed to the app."
                )
            cb_ctx.dash_response.set_data(response_data)
            return cb_ctx.dash_response

        async def _dispatch_async():
            body = request.get_json()
            # pylint: disable=protected-access
            cb_ctx = dash_app._initialize_context(body)
            func = dash_app._prepare_callback(cb_ctx, body)
            args = dash_app._inputs_to_vals(cb_ctx.inputs_list + cb_ctx.states_list)
            ctx = copy_context()
            partial_func = dash_app._execute_callback(
                func, args, cb_ctx.outputs_list, cb_ctx
            )
            response_data = ctx.run(partial_func)
            if asyncio.iscoroutine(response_data):
                response_data = await response_data
            cb_ctx.dash_response.set_data(response_data)
            return cb_ctx.dash_response

        if dash_app._use_async:
            return _dispatch_async
        return _dispatch

    def _serve_default_favicon(self):
        return Response(
            pkgutil.get_data("dash", "favicon.ico"), content_type="image/x-icon"
        )

    def register_timing_hooks(self, _first_run: bool):
        # Define timing hooks inside method scope and register them
        def _before_request() -> None:
            flask_g.timing_information = {  # type: ignore[attr-defined]
                "__dash_server": {"dur": time.time(), "desc": None}
            }

        def _after_request(response: Response):  # type: ignore[name-defined]
            timing_information = flask_g.get("timing_information", None)  # type: ignore[attr-defined]
            if timing_information is None:
                return response
            dash_total = timing_information.get("__dash_server", None)
            if dash_total is not None:
                dash_total["dur"] = round((time.time() - dash_total["dur"]) * 1000)
            for name, info in timing_information.items():
                value = name
                if info.get("desc") is not None:
                    value += f';desc="{info["desc"]}"'
                if info.get("dur") is not None:
                    value += f";dur={info['dur']}"
                response.headers.add("Server-Timing", value)
            return response

        self.before_request(_before_request)
        self.after_request(_after_request)

    def register_callback_api_routes(
        self, callback_api_paths: Dict[str, Callable[..., Any]]
    ):
        """
        Register callback API endpoints on the Flask app.
        Each key in callback_api_paths is a route, each value is a handler (sync or async).
        The view function parses the JSON body and passes it to the handler.
        """
        for path, handler in callback_api_paths.items():
            endpoint = f"dash_callback_api_{path}"
            route = path if path.startswith("/") else f"/{path}"
            methods = ["POST"]

            if inspect.iscoroutinefunction(handler):

                async def _async_view_func(*args, handler=handler, **kwargs):
                    data = request.get_json()
                    result = await handler(**data) if data else await handler()
                    return jsonify(result)

                view_func = _async_view_func
            else:

                def _sync_view_func(*args, handler=handler, **kwargs):
                    data = request.get_json()
                    result = handler(**data) if data else handler()
                    return jsonify(result)

                view_func = _sync_view_func

                view_func = _sync_view_func

            # Flask 2.x+ supports async views natively
            self.server.add_url_rule(
                route, endpoint=endpoint, view_func=view_func, methods=methods
            )

class contains_text:
    def __init__(self, selector, text, timeout):
        self.selector = selector
        self.text = text
        self.timeout = timeout

    def __call__(self, driver):
        try:
            elem = driver.find_element(By.CSS_SELECTOR, self.selector)
            logger.debug("contains text {%s} => expected %s", elem.text, self.text)
            value = elem.get_attribute("value")
            return self.text in str(elem.text) or (
                value is not None and self.text in str(value)
            )
        except WebDriverException:
            return False

    def message(self, driver):
        try:
            element = self._get_element(driver)
            text = "found: " + str(element.text) or str(element.get_attribute("value"))
        except WebDriverException:
            text = f"{self.selector} not found"
        return f"text -> {self.text} not found inside element within {self.timeout}s, {text}"

    def _get_element(self, driver):
        return driver.find_element(By.CSS_SELECTOR, self.selector)

class text_to_equal:
    def __init__(self, selector, text, timeout):
        self.selector = selector
        self.text = text
        self.timeout = timeout

    def __call__(self, driver):
        try:
            elem = self._get_element(driver)
            logger.debug("text to equal {%s} => expected %s", elem.text, self.text)
            value = elem.get_attribute("value")
            return str(elem.text) == self.text or (
                value is not None and str(value) == self.text
            )
        except WebDriverException:
            return False

    def message(self, driver):
        try:
            element = self._get_element(driver)
            text = "found: " + str(element.text) or str(element.get_attribute("value"))
        except WebDriverException:
            text = f"{self.selector} not found"
        return f"text -> {self.text} not found within {self.timeout}s, {text}"

    def _get_element(self, driver):
        return driver.find_element(By.CSS_SELECTOR, self.selector)

def get_backend(
    name: str
) -> tuple[BaseDashServer, RequestAdapter]:
    module_name, server_class, request_class = _backend_imports[name.lower()]
    try:
        module = importlib.import_module(module_name)
        server = getattr(module, server_class)
        request_adapter = getattr(module, request_class)
        return server, request_adapter
    except KeyError as e:
        raise ValueError(f"Unknown backend: {name}") from e
    except ImportError as e:
        raise ImportError(
            f"Could not import module '{module_name}' for backend '{name}': {e}"
        ) from e
    except AttributeError as e:
        raise AttributeError(
            f"Module '{module_name}' does not have class '{server_class}' for backend '{name}': {e}"
        ) from e

def spawn_context():
    torch.multiprocessing.set_start_method('spawn', force=True)
    logging.info("Setting torch.multiprocessing context to 'spawn'")

def checkAndReloadIfNeeded(self):
    now = int(time.time() * 1000)
    if now - self.memory_cache["last_check"] < CACHE_CHECK_INTERVAL_MS:
        return
    self.memory_cache["last_check"] = now

    try:
        file_path = self.getCredentialFilePath()
        stat = file_path.stat()
        file_mod_time = int(stat.st_mtime * 1000)
        if file_mod_time > self.memory_cache["file_mod_time"]:
            await self.reloadCredentialsFromFile()
            self.memory_cache["file_mod_time"] = file_mod_time
    except FileNotFoundError:
        self.memory_cache["file_mod_time"] = 0
    except Exception as e:
        self.memory_cache["credentials"] = None
        raise TokenManagerError(TokenError.FILE_ACCESS_ERROR, str(e), e)

async def getValidCredentials(self, qwen_client: IQwenOAuth2Client, force_refresh: bool = False):
    try:
        self.checkAndReloadIfNeeded()

        if (
            self.memory_cache["credentials"]
            and not force_refresh
            and self.isTokenValid(self.memory_cache["credentials"])
        ):
            return self.memory_cache["credentials"]

        if self.refresh_promise:
            return await self.refresh_promise

        self.refresh_promise = asyncio.create_task(self.performTokenRefresh(qwen_client, force_refresh))
        credentials = await self.refresh_promise
        self.refresh_promise = None
        return credentials
    except Exception as e:
        if isinstance(e, TokenManagerError):
            raise
        raise TokenManagerError(TokenError.REFRESH_FAILED, str(e), e)

async def acquireLock(self, lock_path: Path):
    max_attempts = 50
    attempt_interval = 200  # ms
    lock_id = str(uuid.uuid4())

    for _ in range(max_attempts):
        try:
            with open(lock_path, "w") as f:
                f.write(lock_id)
            return
        except:
            try:
                stat = os.stat(str(lock_path))
                lock_age = int(time.time() * 1000) - int(stat.st_mtime * 1000)
                if lock_age > LOCK_TIMEOUT_MS:
                    try:
                        await os.unlink(str(lock_path))
                    except:
                        pass
            except:
                pass
            await asyncio.sleep(attempt_interval / 1000)
    raise TokenManagerError(TokenError.LOCK_TIMEOUT, "Failed to acquire lock")

async def releaseLock(self, lock_path: Path):
    try:
        await os.unlink(str(lock_path))
    except:
        pass

def load(self) -> Image.core.PixelAccess | None:
    """Load image data based on tile list"""

    if not self.tile and self._im is None:
        msg = "cannot load this image"
        raise OSError(msg)

    pixel = Image.Image.load(self)
    if not self.tile:
        return pixel

    self.map: mmap.mmap | None = None
    use_mmap = self.filename and len(self.tile) == 1

    readonly = 0

    # look for read/seek overrides
    if hasattr(self, "load_read"):
        read = self.load_read
        # don't use mmap if there are custom read/seek functions
        use_mmap = False
    else:
        read = self.fp.read

    if hasattr(self, "load_seek"):
        seek = self.load_seek
        use_mmap = False
    else:
        seek = self.fp.seek

    if use_mmap:
        # try memory mapping
        decoder_name, extents, offset, args = self.tile[0]
        if isinstance(args, str):
            args = (args, 0, 1)
        if (
            decoder_name == "raw"
            and isinstance(args, tuple)
            and len(args) >= 3
            and args[0] == self.mode
            and args[0] in Image._MAPMODES
        ):
            if offset < 0:
                msg = "Tile offset cannot be negative"
                raise ValueError(msg)
            try:
                # use mmap, if possible
                import mmap

                with open(self.filename) as fp:
                    self.map = mmap.mmap(fp.fileno(), 0, access=mmap.ACCESS_READ)
                if offset + self.size[1] * args[1] > self.map.size():
                    msg = "buffer is not large enough"
                    raise OSError(msg)
                self.im = Image.core.map_buffer(
                    self.map, self.size, decoder_name, offset, args
                )
                readonly = 1
                # After trashing self.im,
                # we might need to reload the palette data.
                if self.palette:
                    self.palette.dirty = 1
            except (AttributeError, OSError, ImportError):
                self.map = None

    self.load_prepare()
    err_code = -3  # initialize to unknown error
    if not self.map:
        # sort tiles in file order
        self.tile.sort(key=_tilesort)

        # FIXME: This is a hack to handle TIFF's JpegTables tag.
        prefix = getattr(self, "tile_prefix", b"")

        # Remove consecutive duplicates that only differ by their offset
        self.tile = [
            list(tiles)[-1]
            for _, tiles in itertools.groupby(
                self.tile, lambda tile: (tile[0], tile[1], tile[3])
            )
        ]
        for i, (decoder_name, extents, offset, args) in enumerate(self.tile):
            seek(offset)
            decoder = Image._getdecoder(
                self.mode, decoder_name, args, self.decoderconfig
            )
            try:
                decoder.setimage(self.im, extents)
                if decoder.pulls_fd:
                    decoder.setfd(self.fp)
                    err_code = decoder.decode(b"")[1]
                else:
                    b = prefix
                    while True:
                        read_bytes = self.decodermaxblock
                        if i + 1 < len(self.tile):
                            next_offset = self.tile[i + 1].offset
                            if next_offset > offset:
                                read_bytes = next_offset - offset
                        try:
                            s = read(read_bytes)
                        except (IndexError, struct.error) as e:
                            # truncated png/gif
                            if LOAD_TRUNCATED_IMAGES:
                                break
                            else:
                                msg = "image file is truncated"
                                raise OSError(msg) from e

                        if not s:  # truncated jpeg
                            if LOAD_TRUNCATED_IMAGES:
                                break
                            else:
                                msg = (
                                    "image file is truncated "
                                    f"({len(b)} bytes not processed)"
                                )
                                raise OSError(msg)

                        b = b + s
                        n, err_code = decoder.decode(b)
                        if n < 0:
                            break
                        b = b[n:]
            finally:
                # Need to cleanup here to prevent leaks
                decoder.cleanup()

    self.tile = []
    self.readonly = readonly

    self.load_end()

    if self._exclusive_fp and self._close_exclusive_fp_after_loading:
        self.fp.close()
    self.fp = None

    if not self.map and not LOAD_TRUNCATED_IMAGES and err_code < 0:
        # still raised if decoder fails to return anything
        raise _get_oserror(err_code, encoder=False)

    return Image.Image.load(self)

def mask_1(self) -> Image.Image:
    mask = Image.new("1", (self.size, self.size))
    px = mask.load()
    assert px is not None
    for y in range(mask.height):
        for x in range(mask.width):
            px[y, x] = (x + y) % 2
    return mask

def gradient_L(self) -> Image.Image:
    gradient = Image.new("L", (self.size, self.size))
    px = gradient.load()
    assert px is not None
    for y in range(gradient.height):
        for x in range(gradient.width):
            px[y, x] = (x + y) % 255
    return gradient

def _get_background(
    im: Image.Image,
    info_background: int | tuple[int, int, int] | tuple[int, int, int, int] | None,
) -> int:
    background = 0
    if info_background:
        if isinstance(info_background, tuple):
            # WebPImagePlugin stores an RGBA value in info["background"]
            # So it must be converted to the same format as GifImagePlugin's
            # info["background"] - a global color table index
            assert im.palette is not None
            try:
                background = im.palette.getcolor(info_background, im)
            except ValueError as e:
                if str(e) not in (
                    # If all 256 colors are in use,
                    # then there is no need for the background color
                    "cannot allocate more than 256 colors",
                    # Ignore non-opaque WebP background
                    "cannot add non-opaque RGBA color to RGB palette",
                ):
                    raise
        else:
            background = info_background
    return background

def forward_model(model, model_name, preprocess_val, image_batch, text_batch):
    y = []
    tokenizer = open_clip.get_tokenizer(model_name)
    with torch.no_grad():
        for x_im, x_txt in zip(image_batch, text_batch):
            x_im = torch.stack([preprocess_val(im) for im in x_im])
            x_txt = tokenizer(x_txt)
        y.append(model(x_im, x_txt))
    if type(y[0]) == dict:
        out = {}
        for key in y[0].keys():
            out[key] = torch.stack([batch_out[key] for batch_out in y])
    else:
        out = []
        for i in range(len(y[0])):
            out.append(torch.stack([batch_out[i] for batch_out in y]))
    return out

