def _transform_value(
    self, provider_key: str, param_key: str, value: Any
) -> Any:
    """
    Transform parameter values during mapping.

    This handles provider-specific transformations like:
    - Google: Expanding "en" to "en-US"
    - Google: Wrapping prompt in speech_contexts structure
    - Deepgram: Converting prompt string to keywords list

    Args:
        provider_key: Provider identifier
        param_key: Parameter name (from COMMON_PARAMS)
        value: Parameter value to transform

    Returns:
        Transformed parameter value
    """
    # Google: Expand 2-letter language codes to locale codes
    if provider_key == "google" and param_key == "language":
        if isinstance(value, str) and len(value) == 2:
            return GOOGLE_LANGUAGE_MAP.get(value, f"{value}-US")

    # Google: Wrap prompt in speech_contexts structure
    if provider_key == "google" and param_key == "prompt":
        return [{"phrases": [value]}]

    # Deepgram: Split prompt into keywords list
    if provider_key == "deepgram" and param_key == "prompt":
        if isinstance(value, str):
            return value.split()
        return value

    return value

def test_prefetch_with_missing_saved_values_uses_defaults(self, mock_mongo_db):
    """Test that pre-fetch falls back to defaults when saved values are missing"""
    from application.api.answer.services.stream_processor import StreamProcessor
    from application.core.settings import settings
    from unittest.mock import patch, MagicMock

    tools_collection = mock_mongo_db[settings.MONGO_DB_NAME]["user_tools"]
    tool_id = ObjectId()

    # Tool configuration without saved values
    tools_collection.insert_one(
        {
            "_id": tool_id,
            "name": "cryptoprice",
            "user": "user_123",
            "status": True,
            "actions": [
                {
                    "name": "cryptoprice_get",
                    "description": "Get cryptocurrency price",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "symbol": {
                                "type": "string",
                                "description": "Crypto symbol",
                                "default": "ETH"  # Only default, no saved value
                            },
                            "currency": {
                                "type": "string",
                                "description": "Currency",
                                "default": "EUR"
                            }
                        },
                        "required": ["symbol", "currency"]
                    }
                }
            ],
            "config": {}
        }
    )

    request_data = {
        "question": "Crypto price?",
        "tools": [str(tool_id)]
    }

    processor = StreamProcessor(request_data, {"sub": "user_123"})
    processor._required_tool_actions = {"cryptoprice": {"cryptoprice_get"}}

    with patch("application.agents.tools.tool_manager.ToolManager") as mock_manager_class:
        mock_manager = MagicMock()
        mock_manager_class.return_value = mock_manager

        # Mock the tool instance
        mock_tool = MagicMock()
