def initialize_guardrail(
    guardrail: Dict,
    config_file_path: Optional[str] = None,
) -> Optional[Guardrail]:
    """
    Initialize a guardrail from a dictionary and add it to the litellm callback manager

    Returns a Guardrail object if the guardrail is initialized successfully
    """
    litellm_params_data = guardrail["litellm_params"]
    verbose_proxy_logger.debug("litellm_params= %s", litellm_params_data)

    _litellm_params_kwargs = {
        k: litellm_params_data.get(k) for k in LitellmParams.__annotations__.keys()
    }

    litellm_params = LitellmParams(**_litellm_params_kwargs)  # type: ignore

    if (
        "category_thresholds" in litellm_params_data
        and litellm_params_data["category_thresholds"]
    ):
        lakera_category_thresholds = LakeraCategoryThresholds(
            **litellm_params_data["category_thresholds"]
        )
        litellm_params.category_thresholds = lakera_category_thresholds

    if litellm_params.api_key and litellm_params.api_key.startswith("os.environ/"):
        litellm_params.api_key = str(get_secret(litellm_params.api_key))

    if litellm_params.api_base and litellm_params.api_base.startswith(
        "os.environ/"
    ):
        litellm_params.api_base = str(get_secret(litellm_params.api_base))

    guardrail_type = litellm_params.guardrail
    if guardrail_type is None:
        raise ValueError("guardrail_type is required")

    initializer = guardrail_initializer_registry.get(guardrail_type)

    if initializer:
        initializer(litellm_params, guardrail)
    elif isinstance(guardrail_type, str) and "." in guardrail_type:
        InitializeGuardrails.initialize_custom_guardrail(
            guardrail=guardrail,
            guardrail_type=guardrail_type,
            litellm_params=litellm_params,
            config_file_path=config_file_path,
        )
    else:
        raise ValueError(f"Unsupported guardrail: {guardrail_type}")

    parsed_guardrail = Guardrail(
        guardrail_name=guardrail["guardrail_name"],
        litellm_params=litellm_params,
    )

    return parsed_guardrail

def validate_environment(
    self,
    presidio_analyzer_api_base: Optional[str] = None,
    presidio_anonymizer_api_base: Optional[str] = None,
):
    self.presidio_analyzer_api_base: Optional[
        str
    ] = presidio_analyzer_api_base or get_secret(
        "PRESIDIO_ANALYZER_API_BASE", None
    )  # type: ignore
    self.presidio_anonymizer_api_base: Optional[
        str
    ] = presidio_anonymizer_api_base or litellm.get_secret(
        "PRESIDIO_ANONYMIZER_API_BASE", None
    )  # type: ignore

    if self.presidio_analyzer_api_base is None:
        raise Exception("Missing `PRESIDIO_ANALYZER_API_BASE` from environment")
    if not self.presidio_analyzer_api_base.endswith("/"):
        self.presidio_analyzer_api_base += "/"
    if not (
        self.presidio_analyzer_api_base.startswith("http://")
        or self.presidio_analyzer_api_base.startswith("https://")
    ):
        # add http:// if unset, assume communicating over private network - e.g. render
        self.presidio_analyzer_api_base = (
            "http://" + self.presidio_analyzer_api_base
        )

    if self.presidio_anonymizer_api_base is None:
        raise Exception("Missing `PRESIDIO_ANONYMIZER_API_BASE` from environment")
    if not self.presidio_anonymizer_api_base.endswith("/"):
        self.presidio_anonymizer_api_base += "/"
    if not (
        self.presidio_anonymizer_api_base.startswith("http://")
        or self.presidio_anonymizer_api_base.startswith("https://")
    ):
        # add http:// if unset, assume communicating over private network - e.g. render
        self.presidio_anonymizer_api_base = (
            "http://" + self.presidio_anonymizer_api_base
        )

