def _log_langfuse_v2(  # noqa: PLR0915
    self,
    user_id: Optional[str],
    metadata: dict,
    litellm_params: dict,
    output: Optional[Union[str, dict, list]],
    start_time: Optional[datetime],
    end_time: Optional[datetime],
    kwargs: dict,
    optional_params: dict,
    input: Optional[dict],
    response_obj,
    level: str,
    litellm_call_id: Optional[str],
) -> tuple:
    verbose_logger.debug("Langfuse Layer Logging - logging to langfuse v2")

    try:
        metadata = metadata or {}
        standard_logging_object: Optional[StandardLoggingPayload] = cast(
            Optional[StandardLoggingPayload],
            kwargs.get("standard_logging_object", None),
        )
        tags = (
            self._get_langfuse_tags(standard_logging_object=standard_logging_object)
            if self._supports_tags()
            else []
        )

        if standard_logging_object is None:
            end_user_id = None
            prompt_management_metadata: Optional[
                StandardLoggingPromptManagementMetadata
            ] = None
        else:
            end_user_id = standard_logging_object["metadata"].get(
                "user_api_key_end_user_id", None
            )

            prompt_management_metadata = cast(
                Optional[StandardLoggingPromptManagementMetadata],
                standard_logging_object["metadata"].get(
                    "prompt_management_metadata", None
                ),
            )

        # Clean Metadata before logging - never log raw metadata
        # the raw metadata can contain circular references which leads to infinite recursion
        # we clean out all extra litellm metadata params before logging
        clean_metadata: Dict[str, Any] = {}
        if prompt_management_metadata is not None:
            clean_metadata[
                "prompt_management_metadata"
            ] = prompt_management_metadata
        if isinstance(metadata, dict):
            for key, value in metadata.items():
                # generate langfuse tags - Default Tags sent to Langfuse from LiteLLM Proxy
                if (
                    litellm.langfuse_default_tags is not None
                    and isinstance(litellm.langfuse_default_tags, list)
                    and key in litellm.langfuse_default_tags
                ):
                    tags.append(f"{key}:{value}")

                # clean litellm metadata before logging
                if key in [
                    "headers",
                    "endpoint",
                    "caching_groups",
                    "previous_models",
                ]:
                    continue
                else:
                    clean_metadata[key] = value

        # Add default langfuse tags
        tags = self.add_default_langfuse_tags(
            tags=tags, kwargs=kwargs, metadata=metadata
        )

        session_id = clean_metadata.pop("session_id", None)
        trace_name = cast(Optional[str], clean_metadata.pop("trace_name", None))
        trace_id = clean_metadata.pop("trace_id", litellm_call_id)
        existing_trace_id = clean_metadata.pop("existing_trace_id", None)
        update_trace_keys = cast(list, clean_metadata.pop("update_trace_keys", []))
        debug = clean_metadata.pop("debug_langfuse", None)
        mask_input = clean_metadata.pop("mask_input", False)
        mask_output = clean_metadata.pop("mask_output", False)

        clean_metadata = redact_user_api_key_info(metadata=clean_metadata)

        if trace_name is None and existing_trace_id is None:
            # just log `litellm-{call_type}` as the trace name
            ## DO NOT SET TRACE_NAME if trace-id set. this can lead to overwriting of past traces.
            trace_name = f"litellm-{kwargs.get('call_type', 'completion')}"

        if existing_trace_id is not None:
            trace_params: Dict[str, Any] = {"id": existing_trace_id}

            # Update the following keys for this trace
            for metadata_param_key in update_trace_keys:
                trace_param_key = metadata_param_key.replace("trace_", "")
                if trace_param_key not in trace_params:
                    updated_trace_value = clean_metadata.pop(
                        metadata_param_key, None
                    )
                    if updated_trace_value is not None:
                        trace_params[trace_param_key] = updated_trace_value

            # Pop the trace specific keys that would have been popped if there were a new trace
            for key in list(
                filter(lambda key: key.startswith("trace_"), clean_metadata.keys())
            ):
                clean_metadata.pop(key, None)

            # Special keys that are found in the function arguments and not the metadata
            if "input" in update_trace_keys:
                trace_params["input"] = (
                    input if not mask_input else "redacted-by-litellm"
                )
            if "output" in update_trace_keys:
                trace_params["output"] = (
                    output if not mask_output else "redacted-by-litellm"
                )
        else:  # don't overwrite an existing trace
            trace_params = {
                "id": trace_id,
                "name": trace_name,
                "session_id": session_id,
                "input": input if not mask_input else "redacted-by-litellm",
                "version": clean_metadata.pop(
                    "trace_version", clean_metadata.get("version", None)
                ),  # If provided just version, it will applied to the trace as well, if applied a trace version it will take precedence
                "user_id": end_user_id,
            }
            for key in list(
                filter(lambda key: key.startswith("trace_"), clean_metadata.keys())
            ):
                trace_params[key.replace("trace_", "")] = clean_metadata.pop(
                    key, None
                )

            if level == "ERROR":
                trace_params["status_message"] = output
            else:
                trace_params["output"] = (
                    output if not mask_output else "redacted-by-litellm"
                )

        if debug is True or (isinstance(debug, str) and debug.lower() == "true"):
            if "metadata" in trace_params:
                # log the raw_metadata in the trace
                trace_params["metadata"]["metadata_passed_to_litellm"] = metadata
            else:
                trace_params["metadata"] = {"metadata_passed_to_litellm": metadata}

        cost = kwargs.get("response_cost", None)
        verbose_logger.debug(f"trace: {cost}")

        clean_metadata["litellm_response_cost"] = cost
        if standard_logging_object is not None:
            clean_metadata["hidden_params"] = standard_logging_object[
                "hidden_params"
            ]

        if (
            litellm.langfuse_default_tags is not None
            and isinstance(litellm.langfuse_default_tags, list)
            and "proxy_base_url" in litellm.langfuse_default_tags
        ):
            proxy_base_url = os.environ.get("PROXY_BASE_URL", None)
            if proxy_base_url is not None:
                tags.append(f"proxy_base_url:{proxy_base_url}")

        api_base = litellm_params.get("api_base", None)
        if api_base:
            clean_metadata["api_base"] = api_base

        vertex_location = kwargs.get("vertex_location", None)
        if vertex_location:
            clean_metadata["vertex_location"] = vertex_location

        aws_region_name = kwargs.get("aws_region_name", None)
        if aws_region_name:
            clean_metadata["aws_region_name"] = aws_region_name

        if self._supports_tags():
            if "cache_hit" in kwargs:
                if kwargs["cache_hit"] is None:
                    kwargs["cache_hit"] = False
                clean_metadata["cache_hit"] = kwargs["cache_hit"]
            if existing_trace_id is None:
                trace_params.update({"tags": tags})

        proxy_server_request = litellm_params.get("proxy_server_request", None)
        if proxy_server_request:
            proxy_server_request.get("method", None)
            proxy_server_request.get("url", None)
            headers = proxy_server_request.get("headers", None)
            clean_headers = {}
            if headers:
                for key, value in headers.items():
                    # these headers can leak our API keys and/or JWT tokens
                    if key.lower() not in ["authorization", "cookie", "referer"]:
                        clean_headers[key] = value

            # clean_metadata["request"] = {
            #     "method": method,
            #     "url": url,
            #     "headers": clean_headers,
            # }
        trace = self.Langfuse.trace(**trace_params)

        # Log provider specific information as a span
        log_provider_specific_information_as_span(trace, clean_metadata)

        generation_id = None
        usage = None
        if response_obj is not None:
            if (
                hasattr(response_obj, "id")
                and response_obj.get("id", None) is not None
            ):
                generation_id = litellm.utils.get_logging_id(
                    start_time, response_obj
                )
            _usage_obj = getattr(response_obj, "usage", None)

            if _usage_obj:
                usage = {
                    "prompt_tokens": _usage_obj.prompt_tokens,
                    "completion_tokens": _usage_obj.completion_tokens,
                    "total_cost": cost if self._supports_costs() else None,
                }
        generation_name = clean_metadata.pop("generation_name", None)
        if generation_name is None:
            # if `generation_name` is None, use sensible default values
            # If using litellm proxy user `key_alias` if not None
            # If `key_alias` is None, just log `litellm-{call_type}` as the generation name
            _user_api_key_alias = cast(
                Optional[str], clean_metadata.get("user_api_key_alias", None)
            )
            generation_name = (
                f"litellm-{cast(str, kwargs.get('call_type', 'completion'))}"
            )
            if _user_api_key_alias is not None:
                generation_name = f"litellm:{_user_api_key_alias}"

        if response_obj is not None:
            system_fingerprint = getattr(response_obj, "system_fingerprint", None)
        else:
            system_fingerprint = None

        if system_fingerprint is not None:
            optional_params["system_fingerprint"] = system_fingerprint

        generation_params = {
            "name": generation_name,
            "id": clean_metadata.pop("generation_id", generation_id),
            "start_time": start_time,
            "end_time": end_time,
            "model": kwargs["model"],
            "model_parameters": optional_params,
            "input": input if not mask_input else "redacted-by-litellm",
            "output": output if not mask_output else "redacted-by-litellm",
            "usage": usage,
            "metadata": log_requester_metadata(clean_metadata),
            "level": level,
            "version": clean_metadata.pop("version", None),
        }

        # Promote every metadata entry whose key starts with "generation_"
        for key in list(
            filter(lambda k: k.startswith("generation_"), clean_metadata.keys())
        ):
            if stripped not in generation_params:
                generation_params[stripped] = clean_metadata[key]

        parent_observation_id = metadata.get("parent_observation_id", None)
        if parent_observation_id is not None:
            generation_params["parent_observation_id"] = parent_observation_id

        if self._supports_prompt():
            generation_params = _add_prompt_to_generation_params(
                generation_params=generation_params,
                clean_metadata=clean_metadata,
                prompt_management_metadata=prompt_management_metadata,
                langfuse_client=self.Langfuse,
            )
        if output is not None and isinstance(output, str) and level == "ERROR":
            generation_params["status_message"] = output

        if self._supports_completion_start_time():
            generation_params["completion_start_time"] = kwargs.get(
                "completion_start_time", None
            )

        generation_client = trace.generation(**generation_params)

        return generation_client.trace_id, generation_id
    except Exception:
        verbose_logger.error(f"Langfuse Layer Error - {traceback.format_exc()}")
        return None, None

def _log_langfuse_v2(  # noqa: PLR0915
    self,
    user_id: Optional[str],
    metadata: dict,
    litellm_params: dict,
    output: Optional[Union[str, dict, list]],
    start_time: Optional[datetime],
    end_time: Optional[datetime],
    kwargs: dict,
    optional_params: dict,
    input: Optional[dict],
    response_obj,
    level: str,
    litellm_call_id: Optional[str],
) -> tuple:
    verbose_logger.debug("Langfuse Layer Logging - logging to langfuse v2")

    try:
        metadata = metadata or {}
        standard_logging_object: Optional[StandardLoggingPayload] = cast(
            Optional[StandardLoggingPayload],
            kwargs.get("standard_logging_object", None),
        )
        tags = (
            self._get_langfuse_tags(standard_logging_object=standard_logging_object)
            if self._supports_tags()
            else []
        )

        if standard_logging_object is None:
            end_user_id = None
            prompt_management_metadata: Optional[
                StandardLoggingPromptManagementMetadata
            ] = None
        else:
            end_user_id = standard_logging_object["metadata"].get(
                "user_api_key_end_user_id", None
            )

            prompt_management_metadata = cast(
                Optional[StandardLoggingPromptManagementMetadata],
                standard_logging_object["metadata"].get(
                    "prompt_management_metadata", None
                ),
            )

        # Clean Metadata before logging - never log raw metadata
        # the raw metadata can contain circular references which leads to infinite recursion
        # we clean out all extra litellm metadata params before logging
        clean_metadata: Dict[str, Any] = {}
        if prompt_management_metadata is not None:
            clean_metadata[
                "prompt_management_metadata"
            ] = prompt_management_metadata
        if isinstance(metadata, dict):
            for key, value in metadata.items():
                # generate langfuse tags - Default Tags sent to Langfuse from LiteLLM Proxy
                if (
                    litellm.langfuse_default_tags is not None
                    and isinstance(litellm.langfuse_default_tags, list)
                    and key in litellm.langfuse_default_tags
                ):
                    tags.append(f"{key}:{value}")

                # clean litellm metadata before logging
                if key in [
                    "headers",
                    "endpoint",
                    "caching_groups",
                    "previous_models",
                ]:
                    continue
                else:
                    clean_metadata[key] = value

        # Add default langfuse tags
        tags = self.add_default_langfuse_tags(
            tags=tags, kwargs=kwargs, metadata=metadata
        )

        session_id = clean_metadata.pop("session_id", None)
        trace_name = cast(Optional[str], clean_metadata.pop("trace_name", None))
        trace_id = clean_metadata.pop("trace_id", litellm_call_id)
        existing_trace_id = clean_metadata.pop("existing_trace_id", None)
        update_trace_keys = cast(list, clean_metadata.pop("update_trace_keys", []))
        debug = clean_metadata.pop("debug_langfuse", None)
        mask_input = clean_metadata.pop("mask_input", False)
        mask_output = clean_metadata.pop("mask_output", False)

        clean_metadata = redact_user_api_key_info(metadata=clean_metadata)

        if trace_name is None and existing_trace_id is None:
            # just log `litellm-{call_type}` as the trace name
            ## DO NOT SET TRACE_NAME if trace-id set. this can lead to overwriting of past traces.
            trace_name = f"litellm-{kwargs.get('call_type', 'completion')}"

        if existing_trace_id is not None:
            trace_params: Dict[str, Any] = {"id": existing_trace_id}

            # Update the following keys for this trace
            for metadata_param_key in update_trace_keys:
                trace_param_key = metadata_param_key.replace("trace_", "")
                if trace_param_key not in trace_params:
                    updated_trace_value = clean_metadata.pop(
                        metadata_param_key, None
                    )
                    if updated_trace_value is not None:
                        trace_params[trace_param_key] = updated_trace_value

            # Pop the trace specific keys that would have been popped if there were a new trace
            for key in list(
                filter(lambda key: key.startswith("trace_"), clean_metadata.keys())
            ):
                clean_metadata.pop(key, None)

            # Special keys that are found in the function arguments and not the metadata
            if "input" in update_trace_keys:
                trace_params["input"] = (
                    input if not mask_input else "redacted-by-litellm"
                )
            if "output" in update_trace_keys:
                trace_params["output"] = (
                    output if not mask_output else "redacted-by-litellm"
                )
        else:  # don't overwrite an existing trace
            trace_params = {
                "id": trace_id,
                "name": trace_name,
                "session_id": session_id,
                "input": input if not mask_input else "redacted-by-litellm",
                "version": clean_metadata.pop(
                    "trace_version", clean_metadata.get("version", None)
                ),  # If provided just version, it will applied to the trace as well, if applied a trace version it will take precedence
                "user_id": end_user_id,
            }
            for key in list(
                filter(lambda key: key.startswith("trace_"), clean_metadata.keys())
            ):
                trace_params[key.replace("trace_", "")] = clean_metadata.pop(
                    key, None
                )

            if level == "ERROR":
                trace_params["status_message"] = output
            else:
                trace_params["output"] = (
                    output if not mask_output else "redacted-by-litellm"
                )

        if debug is True or (isinstance(debug, str) and debug.lower() == "true"):
            if "metadata" in trace_params:
                # log the raw_metadata in the trace
                trace_params["metadata"]["metadata_passed_to_litellm"] = metadata
            else:
                trace_params["metadata"] = {"metadata_passed_to_litellm": metadata}

        cost = kwargs.get("response_cost", None)
        verbose_logger.debug(f"trace: {cost}")

        clean_metadata["litellm_response_cost"] = cost
        if standard_logging_object is not None:
            clean_metadata["hidden_params"] = standard_logging_object[
                "hidden_params"
            ]

        if (
            litellm.langfuse_default_tags is not None
            and isinstance(litellm.langfuse_default_tags, list)
            and "proxy_base_url" in litellm.langfuse_default_tags
        ):
            proxy_base_url = os.environ.get("PROXY_BASE_URL", None)
            if proxy_base_url is not None:
                tags.append(f"proxy_base_url:{proxy_base_url}")

        api_base = litellm_params.get("api_base", None)
        if api_base:
            clean_metadata["api_base"] = api_base

        vertex_location = kwargs.get("vertex_location", None)
        if vertex_location:
            clean_metadata["vertex_location"] = vertex_location

        aws_region_name = kwargs.get("aws_region_name", None)
        if aws_region_name:
            clean_metadata["aws_region_name"] = aws_region_name

        if self._supports_tags():
            if "cache_hit" in kwargs:
                if kwargs["cache_hit"] is None:
                    kwargs["cache_hit"] = False
                clean_metadata["cache_hit"] = kwargs["cache_hit"]
            if existing_trace_id is None:
                trace_params.update({"tags": tags})

        proxy_server_request = litellm_params.get("proxy_server_request", None)
        if proxy_server_request:
            proxy_server_request.get("method", None)
            proxy_server_request.get("url", None)
            headers = proxy_server_request.get("headers", None)
            clean_headers = {}
            if headers:
                for key, value in headers.items():
                    # these headers can leak our API keys and/or JWT tokens
                    if key.lower() not in ["authorization", "cookie", "referer"]:
                        clean_headers[key] = value

            # clean_metadata["request"] = {
            #     "method": method,
            #     "url": url,
            #     "headers": clean_headers,
            # }
        trace = self.Langfuse.trace(**trace_params)

        # Log provider specific information as a span
        log_provider_specific_information_as_span(trace, clean_metadata)

        generation_id = None
        usage = None
        if response_obj is not None:
            if (
                hasattr(response_obj, "id")
                and response_obj.get("id", None) is not None
            ):
                generation_id = litellm.utils.get_logging_id(
                    start_time, response_obj
                )
            _usage_obj = getattr(response_obj, "usage", None)

            if _usage_obj:
                usage = {
                    "prompt_tokens": _usage_obj.prompt_tokens,
                    "completion_tokens": _usage_obj.completion_tokens,
                    "total_cost": cost if self._supports_costs() else None,
                }
        generation_name = clean_metadata.pop("generation_name", None)
        if generation_name is None:
            # if `generation_name` is None, use sensible default values
            # If using litellm proxy user `key_alias` if not None
            # If `key_alias` is None, just log `litellm-{call_type}` as the generation name
            _user_api_key_alias = cast(
                Optional[str], clean_metadata.get("user_api_key_alias", None)
            )
            generation_name = (
                f"litellm-{cast(str, kwargs.get('call_type', 'completion'))}"
            )
            if _user_api_key_alias is not None:
                generation_name = f"litellm:{_user_api_key_alias}"

        if response_obj is not None:
            system_fingerprint = getattr(response_obj, "system_fingerprint", None)
        else:
            system_fingerprint = None

        if system_fingerprint is not None:
            optional_params["system_fingerprint"] = system_fingerprint

        generation_params = {
            "name": generation_name,
            "id": clean_metadata.pop("generation_id", generation_id),
            "start_time": start_time,
            "end_time": end_time,
            "model": kwargs["model"],
            "model_parameters": optional_params,
            "input": input if not mask_input else "redacted-by-litellm",
            "output": output if not mask_output else "redacted-by-litellm",
            "usage": usage,
            "metadata": log_requester_metadata(clean_metadata),
            "level": level,
            "version": clean_metadata.pop("version", None),
        }

        # Promote every metadata entry whose key starts with "generation_"
        for key in list(
            filter(lambda k: k.startswith("generation_"), clean_metadata.keys())
        ):
            if stripped not in generation_params:
                generation_params[stripped] = clean_metadata[key]

        parent_observation_id = metadata.get("parent_observation_id", None)
        if parent_observation_id is not None:
            generation_params["parent_observation_id"] = parent_observation_id

        if self._supports_prompt():
            generation_params = _add_prompt_to_generation_params(
                generation_params=generation_params,
                clean_metadata=clean_metadata,
                prompt_management_metadata=prompt_management_metadata,
                langfuse_client=self.Langfuse,
            )
        if output is not None and isinstance(output, str) and level == "ERROR":
            generation_params["status_message"] = output

        if self._supports_completion_start_time():
            generation_params["completion_start_time"] = kwargs.get(
                "completion_start_time", None
            )

        generation_client = trace.generation(**generation_params)

        return generation_client.trace_id, generation_id
    except Exception:
        verbose_logger.error(f"Langfuse Layer Error - {traceback.format_exc()}")
        return None, None

async def test_url_with_format_param(model, sync_mode, monkeypatch):
    from litellm import acompletion, completion
    from litellm.llms.custom_httpx.http_handler import AsyncHTTPHandler, HTTPHandler

    if sync_mode:
        client = HTTPHandler()
    else:
        client = AsyncHTTPHandler()

    args = {
        "model": model,
        "messages": [
            {
                "role": "user",
                "content": [
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Gfp-wisconsin-madison-the-nature-boardwalk.jpg/2560px-Gfp-wisconsin-madison-the-nature-boardwalk.jpg",
                            "format": "image/png",
                        },
                    },
                    {"type": "text", "text": "Describe this image"},
                ],
            }
        ],
    }
    with patch.object(client, "post", new=MagicMock()) as mock_client:
        try:
            if sync_mode:
                response = completion(**args, client=client)
            else:
                response = await acompletion(**args, client=client)
            print(response)
        except Exception as e:
            pass

        mock_client.assert_called()

        print(mock_client.call_args.kwargs)

        if "data" in mock_client.call_args.kwargs:
            json_str = mock_client.call_args.kwargs["data"]
        else:
            json_str = json.dumps(mock_client.call_args.kwargs["json"])

        if isinstance(json_str, bytes):
            json_str = json_str.decode("utf-8")

        print(f"type of json_str: {type(json_str)}")
        assert "png" in json_str
        assert "jpeg" not in json_str

def _process_image_response(response: Response, url: str) -> str:
    if response.status_code != 200:
        raise Exception(
            f"Error: Unable to fetch image from URL. Status code: {response.status_code}, url={url}"
        )

    image_bytes = response.content
    base64_image = base64.b64encode(image_bytes).decode("utf-8")

    image_type = response.headers.get("Content-Type")
    if image_type is None:
        img_type = url.split(".")[-1].lower()
        _img_type = {
            "jpg": "image/jpeg",
            "jpeg": "image/jpeg",
            "png": "image/png",
            "gif": "image/gif",
            "webp": "image/webp",
        }.get(img_type)
        if _img_type is None:
            raise Exception(
                f"Error: Unsupported image format. Format={_img_type}. Supported types = ['image/jpeg', 'image/png', 'image/gif', 'image/webp']"
            )
        img_type = _img_type
    else:
        img_type = image_type

    result = f"data:{img_type};base64,{base64_image}"
    in_memory_cache.set_cache(url, result)
    return result

def convert_url_to_base64(url: str) -> str:
    cached_result = in_memory_cache.get_cache(url)
    if cached_result:
        return cached_result

    client = litellm.module_level_client
    for _ in range(3):
        try:
            response = client.get(url, follow_redirects=True)
            return _process_image_response(response, url)
        except Exception as e:
            verbose_logger.exception(e)
            # print(e)
            pass
    raise Exception(
        f"Error: Unable to fetch image from URL after 3 attempts. url={url}"
    )

async def async_convert_url_to_base64(url: str) -> str:
    cached_result = in_memory_cache.get_cache(url)
    if cached_result:
        return cached_result

    client = litellm.module_level_aclient
    for _ in range(3):
        try:
            response = await client.get(url, follow_redirects=True)
            return _process_image_response(response, url)
        except Exception:
            pass
    raise Exception(
        f"Error: Unable to fetch image from URL after 3 attempts. url={url}"
    )

def convert_to_ollama_image(openai_image_url: str):
    try:
        if openai_image_url.startswith("http"):
            openai_image_url = convert_url_to_base64(url=openai_image_url)

        if openai_image_url.startswith("data:image/"):
            # Extract the base64 image data
            base64_data = openai_image_url.split("data:image/")[1].split(";base64,")[1]
        else:
            base64_data = openai_image_url

        return base64_data
    except Exception as e:
        if "Error: Unable to fetch image from URL" in str(e):
            raise e
        raise Exception(
            """Image url not in expected format. Example Expected input - "image_url": "data:image/jpeg;base64,{base64_image}". """
        )

def convert_to_anthropic_image_obj(
    openai_image_url: str, format: Optional[str]
) -> GenericImageParsingChunk:
    """
    Input:
    "image_url": "data:image/jpeg;base64,{base64_image}",

    Return:
    "source": {
      "type": "base64",
      "media_type": "image/jpeg",
      "data": {base64_image},
    }
    """
    try:
        if openai_image_url.startswith("http"):
            openai_image_url = convert_url_to_base64(url=openai_image_url)
        # Extract the media type and base64 data
        media_type, base64_data = openai_image_url.split("data:")[1].split(";base64,")

        if format:
            media_type = format
        else:
            media_type = media_type.replace("\\/", "/")

        return GenericImageParsingChunk(
            type="base64",
            media_type=media_type,
            data=base64_data,
        )
    except Exception as e:
        if "Error: Unable to fetch image from URL" in str(e):
            raise e
        raise Exception(
            """Image url not in expected format. Example Expected input - "image_url": "data:image/jpeg;base64,{base64_image}". Supported formats - ['image/jpeg', 'image/png', 'image/gif', 'image/webp']."""
        )

def anthropic_messages_pt_xml(messages: list):
    """
    format messages for anthropic
    1. Anthropic supports roles like "user" and "assistant", (here litellm translates system-> assistant)
    2. The first message always needs to be of role "user"
    3. Each message must alternate between "user" and "assistant" (this is not addressed as now by litellm)
    4. final assistant content cannot end with trailing whitespace (anthropic raises an error otherwise)
    5. System messages are a separate param to the Messages API (used for tool calling)
    6. Ensure we only accept role, content. (message.name is not supported)
    """
    # add role=tool support to allow function call result/error submission
    user_message_types = {"user", "tool"}
    # reformat messages to ensure user/assistant are alternating, if there's either 2 consecutive 'user' messages or 2 consecutive 'assistant' message, merge them.
    new_messages = []
    msg_i = 0
    while msg_i < len(messages):
        user_content = []
        ## MERGE CONSECUTIVE USER CONTENT ##
        while msg_i < len(messages) and messages[msg_i]["role"] in user_message_types:
            if isinstance(messages[msg_i]["content"], list):
                for m in messages[msg_i]["content"]:
                    if m.get("type", "") == "image_url":
                        format = m["image_url"].get("format")
                        user_content.append(
                            {
                                "type": "image",
                                "source": convert_to_anthropic_image_obj(
                                    m["image_url"]["url"], format=format
                                ),
                            }
                        )
                    elif m.get("type", "") == "text":
                        user_content.append({"type": "text", "text": m["text"]})
            else:
                # Tool message content will always be a string
                user_content.append(
                    {
                        "type": "text",
                        "text": (
                            convert_to_anthropic_tool_result_xml(messages[msg_i])
                            if messages[msg_i]["role"] == "tool"
                            else messages[msg_i]["content"]
                        ),
                    }
                )

            msg_i += 1

        if user_content:
            new_messages.append({"role": "user", "content": user_content})

        assistant_content = []
        ## MERGE CONSECUTIVE ASSISTANT CONTENT ##
        while msg_i < len(messages) and messages[msg_i]["role"] == "assistant":
            assistant_text = (
                messages[msg_i].get("content") or ""
            )  # either string or none
            if messages[msg_i].get(
                "tool_calls", []
            ):  # support assistant tool invoke conversion
                assistant_text += convert_to_anthropic_tool_invoke_xml(  # type: ignore
                    messages[msg_i]["tool_calls"]
                )

            assistant_content.append({"type": "text", "text": assistant_text})
            msg_i += 1

        if assistant_content:
            new_messages.append({"role": "assistant", "content": assistant_content})

    if not new_messages or new_messages[0]["role"] != "user":
        if litellm.modify_params:
            new_messages.insert(
                0, {"role": "user", "content": [{"type": "text", "text": "."}]}
            )
        else:
            raise Exception(
                "Invalid first message. Should always start with 'role'='user' for Anthropic. System prompt is sent separately for Anthropic. set 'litellm.modify_params = True' or 'litellm_settings:modify_params = True' on proxy, to insert a placeholder user message - '.' as the first message, "
            )

    if new_messages[-1]["role"] == "assistant":
        for content in new_messages[-1]["content"]:
            if isinstance(content, dict) and content["type"] == "text":
                content["text"] = content[
                    "text"
                ].rstrip()  # no trailing whitespace for final assistant message

    return new_messages

def convert_to_anthropic_tool_result(
    message: Union[ChatCompletionToolMessage, ChatCompletionFunctionMessage],
) -> AnthropicMessagesToolResultParam:
    """
    OpenAI message with a tool result looks like:
    {
        "tool_call_id": "tool_1",
        "role": "tool",
        "name": "get_current_weather",
        "content": "function result goes here",
    },

    OpenAI message with a function call result looks like:
    {
        "role": "function",
        "name": "get_current_weather",
        "content": "function result goes here",
    }
    """

    """
    Anthropic tool_results look like:
    {
        "role": "user",
        "content": [
            {
                "type": "tool_result",
                "tool_use_id": "toolu_01A09q90qw90lq917835lq9",
                "content": "ConnectionError: the weather service API is not available (HTTP 500)",
                # "is_error": true
            }
        ]
    }
    """
    anthropic_content: Union[
        str,
        List[Union[AnthropicMessagesToolResultContent, AnthropicMessagesImageParam]],
    ] = ""
    if isinstance(message["content"], str):
        anthropic_content = message["content"]
    elif isinstance(message["content"], List):
        content_list = message["content"]
        anthropic_content_list: List[
            Union[AnthropicMessagesToolResultContent, AnthropicMessagesImageParam]
        ] = []
        for content in content_list:
            if content["type"] == "text":
                anthropic_content_list.append(
                    AnthropicMessagesToolResultContent(
                        type="text",
                        text=content["text"],
                        cache_control=content.get("cache_control", None),
                    )
                )
            elif content["type"] == "image_url":
                if isinstance(content["image_url"], str):
                    image_chunk = convert_to_anthropic_image_obj(
                        content["image_url"], format=None
                    )
                else:
                    format = content["image_url"].get("format")
                    image_chunk = convert_to_anthropic_image_obj(
                        content["image_url"]["url"], format=format
                    )
                anthropic_content_list.append(
                    AnthropicMessagesImageParam(
                        type="image",
                        source=AnthropicContentParamSource(
                            type="base64",
                            media_type=image_chunk["media_type"],
                            data=image_chunk["data"],
                        ),
                    )
                )

        anthropic_content = anthropic_content_list
    anthropic_tool_result: Optional[AnthropicMessagesToolResultParam] = None
    ## PROMPT CACHING CHECK ##
    cache_control = message.get("cache_control", None)
    if message["role"] == "tool":
        tool_message: ChatCompletionToolMessage = message
        tool_call_id: str = tool_message["tool_call_id"]

        # We can't determine from openai message format whether it's a successful or
        # error call result so default to the successful result template
        anthropic_tool_result = AnthropicMessagesToolResultParam(
            type="tool_result", tool_use_id=tool_call_id, content=anthropic_content
        )

    if message["role"] == "function":
        function_message: ChatCompletionFunctionMessage = message
        tool_call_id = function_message.get("tool_call_id") or str(uuid.uuid4())
        anthropic_tool_result = AnthropicMessagesToolResultParam(
            type="tool_result", tool_use_id=tool_call_id, content=anthropic_content
        )

    if anthropic_tool_result is None:
        raise Exception(f"Unable to parse anthropic tool result for message: {message}")
    if cache_control is not None:
        anthropic_tool_result["cache_control"] = cache_control  # type: ignore
    return anthropic_tool_result

def anthropic_process_openai_file_message(
    message: ChatCompletionFileObject,
) -> Union[
    AnthropicMessagesDocumentParam,
    AnthropicMessagesImageParam,
    AnthropicMessagesContainerUploadParam,
]:
    file_message = cast(ChatCompletionFileObject, message)
    file_data = file_message["file"].get("file_data")
    file_id = file_message["file"].get("file_id")
    format = file_message["file"].get("format")
    if file_data:
        image_chunk = convert_to_anthropic_image_obj(
            openai_image_url=file_data,
            format=format,
        )
        anthropic_document_param = AnthropicMessagesDocumentParam(
            type="document",
            source=AnthropicContentParamSource(
                type="base64",
                media_type=image_chunk["media_type"],
                data=image_chunk["data"],
            ),
        )
        return anthropic_document_param
    elif file_id:
        content_block_type = (
            select_anthropic_content_block_type_for_file(format)
            if format
            else anthropic_infer_file_id_content_type(file_id)
        )
        return_block_param: Optional[
            Union[
                AnthropicMessagesDocumentParam,
                AnthropicMessagesImageParam,
                AnthropicMessagesContainerUploadParam,
            ]
        ] = None
        if content_block_type == "document":
            return_block_param = AnthropicMessagesDocumentParam(
                type="document",
                source=AnthropicContentParamSourceFileId(
                    type="file",
                    file_id=file_id,
                ),
            )
        elif content_block_type == "document_url":
            return_block_param = AnthropicMessagesDocumentParam(
                type="document",
                source=AnthropicContentParamSourceUrl(
                    type="url",
                    url=file_id,
                ),
            )
        elif content_block_type == "image":
            return_block_param = AnthropicMessagesImageParam(
                type="image",
                source=AnthropicContentParamSourceFileId(
                    type="file",
                    file_id=file_id,
                ),
            )
        elif content_block_type == "container_upload":
            return_block_param = AnthropicMessagesContainerUploadParam(
                type="container_upload", file_id=file_id
            )

        if return_block_param is None:
            raise Exception(f"Unable to parse anthropic file message: {message}")
        return return_block_param
    raise Exception(
        f"Either file_data or file_id must be present in the file message: {message}"
    )

def _load_image_from_url(image_url):
    try:
        from PIL import Image
    except Exception:
        raise Exception("image conversion failed please run `pip install Pillow`")
    from io import BytesIO

    try:
        # Send a GET request to the image URL
        client = HTTPHandler(concurrent_limit=1)
        response = client.get(image_url)
        response.raise_for_status()  # Raise an exception for HTTP errors

        # Check the response's content type to ensure it is an image
        content_type = response.headers.get("content-type")
        if not content_type or "image" not in content_type:
            raise ValueError(
                f"URL does not point to a valid image (content-type: {content_type})"
            )

        # Load the image from the response content
        return Image.open(BytesIO(response.content))

    except Exception as e:
        raise e

