def add_openai_metadata(metadata: dict) -> dict:
    """
    Add metadata to openai optional parameters, excluding hidden params.

    OpenAI 'metadata' only supports string values.

    Args:
        params (dict): Dictionary of API parameters
        metadata (dict, optional): Metadata to include in the request

    Returns:
        dict: Updated parameters dictionary with visible metadata only
    """
    if metadata is None:
        return None
    # Only include non-hidden parameters
    visible_metadata = {
        k: v
        for k, v in metadata.items()
        if k != "hidden_params" and isinstance(v, (str))
    }

    # max 16 keys allowed by openai - trim down to 16
    if len(visible_metadata) > 16:
        filtered_metadata = {}
        idx = 0
        for k, v in visible_metadata.items():
            if idx < 16:
                filtered_metadata[k] = v
            idx += 1
        visible_metadata = filtered_metadata

    return visible_metadata.copy()

def __next__(self):
    from .transformation import LiteLLMAnthropicMessagesAdapter

    try:
        if self.sent_first_chunk is False:
            self.sent_first_chunk = True
            return {
                "type": "message_start",
                "message": {
                    "id": "msg_{}".format(uuid.uuid4()),
                    "type": "message",
                    "role": "assistant",
                    "content": [],
                    "model": self.model,
                    "stop_reason": None,
                    "stop_sequence": None,
                    "usage": UsageDelta(input_tokens=0, output_tokens=0),
                },
            }
        if self.sent_content_block_start is False:
            self.sent_content_block_start = True
            return {
                "type": "content_block_start",
                "index": self.current_content_block_index,
                "content_block": {"type": "text", "text": ""},
            }

        # Handle pending new content block start
        if self.pending_new_content_block:
            self.pending_new_content_block = False
            self.sent_content_block_finish = False  # Reset for new block
            return {
                "type": "content_block_start",
                "index": self.current_content_block_index,
                "content_block": self.current_content_block_start,
            }

        for chunk in self.completion_stream:
            if chunk == "None" or chunk is None:
                raise Exception

            should_start_new_block = self._should_start_new_content_block(chunk)
            if should_start_new_block:
                self._increment_content_block_index()

            processed_chunk = LiteLLMAnthropicMessagesAdapter().translate_streaming_openai_response_to_anthropic(
                response=chunk,
                current_content_block_index=self.current_content_block_index,
            )

            # Check if we need to start a new content block
            # This is where you'd add your logic to detect when a new content block should start
            # For example, if the chunk indicates a tool call or different content type

            if should_start_new_block and not self.sent_content_block_finish:
                # End current content block and prepare for new one
                self.holding_chunk = processed_chunk
                self.sent_content_block_finish = True
                self.pending_new_content_block = True
                return {
                    "type": "content_block_stop",
                    "index": max(self.current_content_block_index - 1, 0),
                }

            if (
                processed_chunk["type"] == "message_delta"
                and self.sent_content_block_finish is False
            ):
                self.holding_chunk = processed_chunk
                self.sent_content_block_finish = True
                return {
                    "type": "content_block_stop",
                    "index": self.current_content_block_index,
                }
            elif self.holding_chunk is not None:
                return_chunk = self.holding_chunk
                self.holding_chunk = processed_chunk
                return return_chunk
            else:
                return processed_chunk
        if self.holding_chunk is not None:
            return_chunk = self.holding_chunk
            self.holding_chunk = None
            return return_chunk
        if self.sent_last_message is False:
            self.sent_last_message = True
            return {"type": "message_stop"}
        raise StopIteration
    except StopIteration:
        if self.sent_last_message is False:
            self.sent_last_message = True
            return {"type": "message_stop"}
        raise StopIteration
    except Exception as e:
        verbose_logger.error(
            "Anthropic Adapter - {}\n{}".format(e, traceback.format_exc())
        )
        raise StopAsyncIteration

def _add_reasoning_system_prompt_if_needed(
    self, 
    messages: List[AllMessageValues], 
    optional_params: dict
) -> List[AllMessageValues]:
    """
    Add reasoning system prompt for Mistral magistral models when reasoning_effort is specified.
    """
    if not optional_params.get("_add_reasoning_prompt", False):
        return messages

    # Check if there's already a system message
    has_system_message = any(msg.get("role") == "system" for msg in messages)

    if has_system_message:
        # Prepend reasoning instructions to existing system message
        for i, msg in enumerate(messages):
            if msg.get("role") == "system":
                existing_content = msg.get("content", "")
                reasoning_prompt = self._get_mistral_reasoning_system_prompt()

                # Handle both string and list content
                if isinstance(existing_content, str):
                    # String content - prepend reasoning prompt
                    new_content = f"{reasoning_prompt}\n\n{existing_content}"
                elif isinstance(existing_content, list):
                    # List content - prepend reasoning prompt as text block
                    new_content = [
                        {"type": "text", "text": reasoning_prompt + "\n\n"}
                    ] + existing_content
                else:
                    # Fallback for any other type - convert to string
                    new_content = f"{reasoning_prompt}\n\n{str(existing_content)}"

                messages[i] = cast(AllMessageValues, {
                    **msg,
                    "content": new_content
                })
                break
    else:
        # Add new system message with reasoning instructions
        reasoning_message: AllMessageValues = cast(AllMessageValues, {
            "role": "system",
            "content": self._get_mistral_reasoning_system_prompt()
        })
        messages = [reasoning_message] + messages

    # Remove the internal flag
    optional_params.pop("_add_reasoning_prompt", None)
    return messages

