def success_handler(  # noqa: PLR0915
    self, result=None, start_time=None, end_time=None, cache_hit=None, **kwargs
):
    verbose_logger.debug(
        f"Logging Details LiteLLM-Success Call: Cache_hit={cache_hit}"
    )
    if not self.should_run_logging(
        event_type="sync_success"
    ):  # prevent double logging
        return
    start_time, end_time, result = self._success_handler_helper_fn(
        start_time=start_time,
        end_time=end_time,
        result=result,
        cache_hit=cache_hit,
        standard_logging_object=kwargs.get("standard_logging_object", None),
    )
    try:
        ## BUILD COMPLETE STREAMED RESPONSE
        complete_streaming_response: Optional[
            Union[ModelResponse, TextCompletionResponse, ResponsesAPIResponse]
        ] = None
        if "complete_streaming_response" in self.model_call_details:
            return  # break out of this.
        complete_streaming_response = self._get_assembled_streaming_response(
            result=result,
            start_time=start_time,
            end_time=end_time,
            is_async=False,
            streaming_chunks=self.sync_streaming_chunks,
        )
        if complete_streaming_response is not None:
            verbose_logger.debug(
                "Logging Details LiteLLM-Success Call streaming complete"
            )
            self.model_call_details["complete_streaming_response"] = (
                complete_streaming_response
            )
            self.model_call_details["response_cost"] = (
                self._response_cost_calculator(result=complete_streaming_response)
            )
            ## STANDARDIZED LOGGING PAYLOAD
            self.model_call_details["standard_logging_object"] = (
                get_standard_logging_object_payload(
                    kwargs=self.model_call_details,
                    init_response_obj=complete_streaming_response,
                    start_time=start_time,
                    end_time=end_time,
                    logging_obj=self,
                    status="success",
                    standard_built_in_tools_params=self.standard_built_in_tools_params,
                )
            )
        callbacks = self.get_combined_callback_list(
            dynamic_success_callbacks=self.dynamic_success_callbacks,
            global_callbacks=litellm.success_callback,
        )

        ## REDACT MESSAGES ##
        result = redact_message_input_output_from_logging(
            model_call_details=(
                self.model_call_details
                if hasattr(self, "model_call_details")
                else {}
            ),
            result=result,
        )
        ## LOGGING HOOK ##
        for callback in callbacks:
            if isinstance(callback, CustomLogger):
                self.model_call_details, result = callback.logging_hook(
                    kwargs=self.model_call_details,
                    result=result,
                    call_type=self.call_type,
                )

        self.has_run_logging(event_type="sync_success")
        for callback in callbacks:
            try:
                litellm_params = self.model_call_details.get("litellm_params", {})
                should_run = self.should_run_callback(
                    callback=callback,
                    litellm_params=litellm_params,
                    event_hook="success_handler",
                )
                if not should_run:
                    continue
                if callback == "promptlayer" and promptLayerLogger is not None:
                    print_verbose("reaches promptlayer for logging!")
                    promptLayerLogger.log_event(
                        kwargs=self.model_call_details,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                    )
                if callback == "supabase" and supabaseClient is not None:
                    print_verbose("reaches supabase for logging!")
                    kwargs = self.model_call_details

                    # this only logs streaming once, complete_streaming_response exists i.e when stream ends
                    if self.stream:
                        if "complete_streaming_response" not in kwargs:
                            continue
                        else:
                            print_verbose("reaches supabase for streaming logging!")
                            result = kwargs["complete_streaming_response"]

                    model = kwargs["model"]
                    messages = kwargs["messages"]
                    optional_params = kwargs.get("optional_params", {})
                    litellm_params = kwargs.get("litellm_params", {})
                    supabaseClient.log_event(
                        model=model,
                        messages=messages,
                        end_user=optional_params.get("user", "default"),
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        litellm_call_id=litellm_params.get(
                            "litellm_call_id", str(uuid.uuid4())
                        ),
                        print_verbose=print_verbose,
                    )
                if callback == "wandb" and weightsBiasesLogger is not None:
                    print_verbose("reaches wandb for logging!")
                    weightsBiasesLogger.log_event(
                        kwargs=self.model_call_details,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                    )
                if callback == "logfire" and logfireLogger is not None:
                    verbose_logger.debug("reaches logfire for success logging!")
                    kwargs = {}
                    for k, v in self.model_call_details.items():
                        if (
                            k != "original_response"
                        ):  # copy.deepcopy raises errors as this could be a coroutine
                            kwargs[k] = v

                    # this only logs streaming once, complete_streaming_response exists i.e when stream ends
                    if self.stream:
                        if "complete_streaming_response" not in kwargs:
                            continue
                        else:
                            print_verbose("reaches logfire for streaming logging!")
                            result = kwargs["complete_streaming_response"]

                    logfireLogger.log_event(
                        kwargs=self.model_call_details,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                        level=LogfireLevel.INFO.value,  # type: ignore
                    )

                if callback == "lunary" and lunaryLogger is not None:
                    print_verbose("reaches lunary for logging!")
                    model = self.model
                    kwargs = self.model_call_details

                    input = kwargs.get("messages", kwargs.get("input", None))

                    type = (
                        "embed"
                        if self.call_type == CallTypes.embedding.value
                        else "llm"
                    )

                    # this only logs streaming once, complete_streaming_response exists i.e when stream ends
                    if self.stream:
                        if "complete_streaming_response" not in kwargs:
                            continue
                        else:
                            result = kwargs["complete_streaming_response"]

                    lunaryLogger.log_event(
                        type=type,
                        kwargs=kwargs,
                        event="end",
                        model=model,
                        input=input,
                        user_id=kwargs.get("user", None),
                        # user_props=self.model_call_details.get("user_props", None),
                        extra=kwargs.get("optional_params", {}),
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        run_id=self.litellm_call_id,
                        print_verbose=print_verbose,
                    )
                if callback == "helicone" and heliconeLogger is not None:
                    print_verbose("reaches helicone for logging!")
                    model = self.model
                    messages = self.model_call_details["input"]
                    kwargs = self.model_call_details

                    # this only logs streaming once, complete_streaming_response exists i.e when stream ends
                    if self.stream:
                        if "complete_streaming_response" not in kwargs:
                            continue
                        else:
                            print_verbose("reaches helicone for streaming logging!")
                            result = kwargs["complete_streaming_response"]

                    heliconeLogger.log_success(
                        model=model,
                        messages=messages,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                        kwargs=kwargs,
                    )
                if callback == "langfuse":
                    global langFuseLogger
                    print_verbose("reaches langfuse for success logging!")
                    kwargs = {}
                    for k, v in self.model_call_details.items():
                        if (
                            k != "original_response"
                        ):  # copy.deepcopy raises errors as this could be a coroutine
                            kwargs[k] = v
                    # this only logs streaming once, complete_streaming_response exists i.e when stream ends
                    if self.stream:
                        verbose_logger.debug(
                            f"is complete_streaming_response in kwargs: {kwargs.get('complete_streaming_response', None)}"
                        )
                        if complete_streaming_response is None:
                            continue
                        else:
                            print_verbose("reaches langfuse for streaming logging!")
                            result = kwargs["complete_streaming_response"]

                    langfuse_logger_to_use = LangFuseHandler.get_langfuse_logger_for_request(
                        globalLangfuseLogger=langFuseLogger,
                        standard_callback_dynamic_params=self.standard_callback_dynamic_params,
                        in_memory_dynamic_logger_cache=in_memory_dynamic_logger_cache,
                    )
                    if langfuse_logger_to_use is not None:
                        _response = langfuse_logger_to_use.log_event_on_langfuse(
                            kwargs=kwargs,
                            response_obj=result,
                            start_time=start_time,
                            end_time=end_time,
                            user_id=kwargs.get("user", None),
                        )
                        if _response is not None and isinstance(_response, dict):
                            _trace_id = _response.get("trace_id", None)
                            if _trace_id is not None:
                                in_memory_trace_id_cache.set_cache(
                                    litellm_call_id=self.litellm_call_id,
                                    service_name="langfuse",
                                    trace_id=_trace_id,
                                )
                if callback == "greenscale" and greenscaleLogger is not None:
                    kwargs = {}
                    for k, v in self.model_call_details.items():
                        if (
                            k != "original_response"
                        ):  # copy.deepcopy raises errors as this could be a coroutine
                            kwargs[k] = v
                    # this only logs streaming once, complete_streaming_response exists i.e when stream ends
                    if self.stream:
                        verbose_logger.debug(
                            f"is complete_streaming_response in kwargs: {kwargs.get('complete_streaming_response', None)}"
                        )
                        if complete_streaming_response is None:
                            continue
                        else:
                            print_verbose(
                                "reaches greenscale for streaming logging!"
                            )
                            result = kwargs["complete_streaming_response"]

                    greenscaleLogger.log_event(
                        kwargs=kwargs,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                    )
                if callback == "athina" and athinaLogger is not None:
                    deep_copy = {}
                    for k, v in self.model_call_details.items():
                        deep_copy[k] = v
                    athinaLogger.log_event(
                        kwargs=deep_copy,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                    )
                if callback == "traceloop":
                    deep_copy = {}
                    for k, v in self.model_call_details.items():
                        if k != "original_response":
                            deep_copy[k] = v
                    traceloopLogger.log_event(
                        kwargs=deep_copy,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        user_id=kwargs.get("user", None),
                        print_verbose=print_verbose,
                    )
                if callback == "s3":
                    global s3Logger
                    if s3Logger is None:
                        s3Logger = S3Logger()
                    if self.stream:
                        if "complete_streaming_response" in self.model_call_details:
                            print_verbose(
                                "S3Logger Logger: Got Stream Event - Completed Stream Response"
                            )
                            s3Logger.log_event(
                                kwargs=self.model_call_details,
                                response_obj=self.model_call_details[
                                    "complete_streaming_response"
                                ],
                                start_time=start_time,
                                end_time=end_time,
                                print_verbose=print_verbose,
                            )
                        else:
                            print_verbose(
                                "S3Logger Logger: Got Stream Event - No complete stream response as yet"
                            )
                    else:
                        s3Logger.log_event(
                            kwargs=self.model_call_details,
                            response_obj=result,
                            start_time=start_time,
                            end_time=end_time,
                            print_verbose=print_verbose,
                        )

                if (
                    callback == "openmeter"
                    and self.model_call_details.get("litellm_params", {}).get(
                        "acompletion", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "aembedding", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "aimage_generation", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "atranscription", False
                    )
                    is not True
                ):
                    global openMeterLogger
                    if openMeterLogger is None:
                        print_verbose("Instantiates openmeter client")
                        openMeterLogger = OpenMeterLogger()
                    if self.stream and complete_streaming_response is None:
                        openMeterLogger.log_stream_event(
                            kwargs=self.model_call_details,
                            response_obj=result,
                            start_time=start_time,
                            end_time=end_time,
                        )
                    else:
                        if self.stream and complete_streaming_response:
                            self.model_call_details["complete_response"] = (
                                self.model_call_details.get(
                                    "complete_streaming_response", {}
                                )
                            )
                            result = self.model_call_details["complete_response"]
                        openMeterLogger.log_success_event(
                            kwargs=self.model_call_details,
                            response_obj=result,
                            start_time=start_time,
                            end_time=end_time,
                        )
                if (
                    isinstance(callback, CustomLogger)
                    and self.model_call_details.get("litellm_params", {}).get(
                        "acompletion", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "aembedding", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "aimage_generation", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "atranscription", False
                    )
                    is not True
                    and self.call_type
                    != CallTypes.pass_through.value  # pass-through endpoints call async_log_success_event
                ):  # custom logger class
                    if self.stream and complete_streaming_response is None:
                        callback.log_stream_event(
                            kwargs=self.model_call_details,
                            response_obj=result,
                            start_time=start_time,
                            end_time=end_time,
                        )
                    else:
                        if self.stream and complete_streaming_response:
                            self.model_call_details["complete_response"] = (
                                self.model_call_details.get(
                                    "complete_streaming_response", {}
                                )
                            )
                            result = self.model_call_details["complete_response"]

                        callback.log_success_event(
                            kwargs=self.model_call_details,
                            response_obj=result,
                            start_time=start_time,
                            end_time=end_time,
                        )
                if (
                    callable(callback) is True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "acompletion", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "aembedding", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "aimage_generation", False
                    )
                    is not True
                    and self.model_call_details.get("litellm_params", {}).get(
                        "atranscription", False
                    )
                    is not True
                    and customLogger is not None
                ):  # custom logger functions
                    print_verbose(
                        "success callbacks: Running Custom Callback Function - {}".format(
                            callback
                        )
                    )

                    customLogger.log_event(
                        kwargs=self.model_call_details,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                        callback_func=callback,
                    )

            except Exception as e:
                print_verbose(
                    f"LiteLLM.LoggingError: [Non-Blocking] Exception occurred while success logging with integrations {traceback.format_exc()}"
                )
                print_verbose(
                    f"LiteLLM.Logging: is sentry capture exception initialized {capture_exception}"
                )
                if capture_exception:  # log this error to sentry for debugging
                    capture_exception(e)
    except Exception as e:
        verbose_logger.exception(
            "LiteLLM.LoggingError: [Non-Blocking] Exception occurred while success logging {}".format(
                str(e)
            ),
        )

def _process_image_response(response: Response, url: str) -> str:
    if response.status_code != 200:
        raise Exception(
            f"Error: Unable to fetch image from URL. Status code: {response.status_code}, url={url}"
        )

    image_bytes = response.content
    base64_image = base64.b64encode(image_bytes).decode("utf-8")

    image_type = response.headers.get("Content-Type")
    if image_type is None:
        img_type = url.split(".")[-1].lower()
        _img_type = {
            "jpg": "image/jpeg",
            "jpeg": "image/jpeg",
            "png": "image/png",
            "gif": "image/gif",
            "webp": "image/webp",
        }.get(img_type)
        if _img_type is None:
            raise Exception(
                f"Error: Unsupported image format. Format={_img_type}. Supported types = ['image/jpeg', 'image/png', 'image/gif', 'image/webp']"
            )
        img_type = _img_type
    else:
        img_type = image_type

    result = f"data:{img_type};base64,{base64_image}"
    in_memory_cache.set_cache(url, result)
    return result

def convert_url_to_base64(url: str) -> str:
    cached_result = in_memory_cache.get_cache(url)
    if cached_result:
        return cached_result

    client = litellm.module_level_client
    for _ in range(3):
        try:
            response = client.get(url, follow_redirects=True)
            return _process_image_response(response, url)
        except Exception as e:
            verbose_logger.exception(e)
            # print(e)
            pass
    raise Exception(
        f"Error: Unable to fetch image from URL after 3 attempts. url={url}"
    )

async def test_url_with_format_param(model, sync_mode, monkeypatch):
    from litellm import acompletion, completion
    from litellm.llms.custom_httpx.http_handler import AsyncHTTPHandler, HTTPHandler

    if sync_mode:
        client = HTTPHandler()
    else:
        client = AsyncHTTPHandler()

    args = {
        "model": model,
        "messages": [
            {
                "role": "user",
                "content": [
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Gfp-wisconsin-madison-the-nature-boardwalk.jpg/2560px-Gfp-wisconsin-madison-the-nature-boardwalk.jpg",
                            "format": "image/png",
                        },
                    },
                    {"type": "text", "text": "Describe this image"},
                ],
            }
        ],
    }
    with patch.object(client, "post", new=MagicMock()) as mock_client:
        try:
            if sync_mode:
                response = completion(**args, client=client)
            else:
                response = await acompletion(**args, client=client)
            print(response)
        except Exception as e:
            pass

        mock_client.assert_called()

        print(mock_client.call_args.kwargs)

        if "data" in mock_client.call_args.kwargs:
            json_str = mock_client.call_args.kwargs["data"]
        else:
            json_str = json.dumps(mock_client.call_args.kwargs["json"])

        if isinstance(json_str, bytes):
            json_str = json_str.decode("utf-8")

        print(f"type of json_str: {type(json_str)}")
        assert "png" in json_str
        assert "jpeg" not in json_str

def get_api_base(
    model: str, optional_params: Union[dict, LiteLLM_Params]
) -> Optional[str]:
    """
    Returns the api base used for calling the model.

    Parameters:
    - model: str - the model passed to litellm.completion()
    - optional_params - the 'litellm_params' in router.completion *OR* additional params passed to litellm.completion - eg. api_base, api_key, etc. See `LiteLLM_Params` - https://github.com/BerriAI/litellm/blob/f09e6ba98d65e035a79f73bc069145002ceafd36/litellm/router.py#L67

    Returns:
    - string (api_base) or None

    Example:
    ```
    from litellm import get_api_base

    get_api_base(model="gemini/gemini-pro")
    ```
    """

    try:
        if isinstance(optional_params, LiteLLM_Params):
            _optional_params = optional_params
        elif "model" in optional_params:
            _optional_params = LiteLLM_Params(**optional_params)
        else:  # prevent needing to copy and pop the dict
            _optional_params = LiteLLM_Params(
                model=model, **optional_params
            )  # convert to pydantic object
    except Exception:
        return None
    # get llm provider

    if _optional_params.api_base is not None:
        return _optional_params.api_base

    if litellm.model_alias_map and model in litellm.model_alias_map:
        model = litellm.model_alias_map[model]
    try:
        (
            model,
            custom_llm_provider,
            dynamic_api_key,
            dynamic_api_base,
        ) = get_llm_provider(
            model=model,
            custom_llm_provider=_optional_params.custom_llm_provider,
            api_base=_optional_params.api_base,
            api_key=_optional_params.api_key,
        )
    except Exception as e:
        verbose_logger.debug("Error occurred in getting api base - {}".format(str(e)))
        custom_llm_provider = None
        dynamic_api_base = None

    if dynamic_api_base is not None:
        return dynamic_api_base

    stream: bool = getattr(optional_params, "stream", False)

    if (
        _optional_params.vertex_location is not None
        and _optional_params.vertex_project is not None
    ):
        from litellm.llms.vertex_ai.vertex_llm_base import VertexBase
        from litellm.types.llms.vertex_ai import VertexPartnerProvider

        if "claude" in model:
            _api_base = VertexBase.create_vertex_url(
                vertex_location=_optional_params.vertex_location,
                vertex_project=_optional_params.vertex_project,
                model=model,
                stream=stream,
                partner=VertexPartnerProvider.claude,
            )
        else:
            if stream:
                _api_base = "{}-aiplatform.googleapis.com/v1/projects/{}/locations/{}/publishers/google/models/{}:streamGenerateContent".format(
                    _optional_params.vertex_location,
                    _optional_params.vertex_project,
                    _optional_params.vertex_location,
                    model,
                )
            else:
                _api_base = "{}-aiplatform.googleapis.com/v1/projects/{}/locations/{}/publishers/google/models/{}:generateContent".format(
                    _optional_params.vertex_location,
                    _optional_params.vertex_project,
                    _optional_params.vertex_location,
                    model,
                )
        return _api_base

    if custom_llm_provider is None:
        return None

    if custom_llm_provider == "gemini":
        if stream:
            _api_base = "https://generativelanguage.googleapis.com/v1beta/models/{}:streamGenerateContent".format(
                model
            )
        else:
            _api_base = "https://generativelanguage.googleapis.com/v1beta/models/{}:generateContent".format(
                model
            )
        return _api_base
    elif custom_llm_provider == "openai":
        _api_base = "https://api.openai.com"
        return _api_base
    return None

