def insert_one(self, doc):
    key = (doc["user_id"], doc["tool_id"], int(doc["todo_id"]))
    self.docs[key] = doc
    return type("res", (), {"inserted_id": key})

def find_one(self, query):
    key = (query.get("user_id"), query.get("tool_id"), int(query.get("todo_id")))
    return self.docs.get(key)

def find(self, query):
    user_id = query.get("user_id")
    tool_id = query.get("tool_id")
    filtered = [
        doc for (uid, tid, _), doc in self.docs.items()
        if uid == user_id and tid == tool_id
    ]
    return FakeCursor(filtered)

def update_one(self, query, update, upsert=False):
    key = (query.get("user_id"), query.get("tool_id"), int(query.get("todo_id")))
    if key in self.docs:
        self.docs[key].update(update.get("$set", {}))
        return type("res", (), {"matched_count": 1})
    elif upsert:
        new_doc = {**query, **update.get("$set", {})}
        self.docs[key] = new_doc
        return type("res", (), {"matched_count": 1})
    else:
        return type("res", (), {"matched_count": 0})

def delete_one(self, query):
    key = (query.get("user_id"), query.get("tool_id"), int(query.get("todo_id")))
    if key in self.docs:
        del self.docs[key]
        return type("res", (), {"deleted_count": 1})
    return type("res", (), {"deleted_count": 0})

def create_agent(cls, type, *args, **kwargs):
    agent_class = cls.agents.get(type.lower())
    if not agent_class:
        raise ValueError(f"No agent class found for type {type}")

    return agent_class(*args, **kwargs)

def save_conversation(
    self,
    conversation_id: Optional[str],
    question: str,
    response: str,
    thought: str,
    sources: List[Dict[str, Any]],
    tool_calls: List[Dict[str, Any]],
    llm: Any,
    model_id: str,
    decoded_token: Dict[str, Any],
    index: Optional[int] = None,
    api_key: Optional[str] = None,
    agent_id: Optional[str] = None,
    is_shared_usage: bool = False,
    shared_token: Optional[str] = None,
    attachment_ids: Optional[List[str]] = None,
) -> str:
    """Save or update a conversation in the database"""
    user_id = decoded_token.get("sub")
    if not user_id:
        raise ValueError("User ID not found in token")
    current_time = datetime.now(timezone.utc)

    # clean up in sources array such that we save max 1k characters for text part
    for source in sources:
        if "text" in source and isinstance(source["text"], str):
            source["text"] = source["text"][:1000]

    if conversation_id is not None and index is not None:
        # Update existing conversation with new query

        result = self.conversations_collection.update_one(
            {
                "_id": ObjectId(conversation_id),
                "user": user_id,
                f"queries.{index}": {"$exists": True},
            },
            {
                "$set": {
                    f"queries.{index}.prompt": question,
                    f"queries.{index}.response": response,
                    f"queries.{index}.thought": thought,
                    f"queries.{index}.sources": sources,
                    f"queries.{index}.tool_calls": tool_calls,
                    f"queries.{index}.timestamp": current_time,
                    f"queries.{index}.attachments": attachment_ids,
                    f"queries.{index}.model_id": model_id,
                }
            },
        )

        if result.matched_count == 0:
            raise ValueError("Conversation not found or unauthorized")
        self.conversations_collection.update_one(
            {
                "_id": ObjectId(conversation_id),
                "user": user_id,
                f"queries.{index}": {"$exists": True},
            },
            {"$push": {"queries": {"$each": [], "$slice": index + 1}}},
        )
        return conversation_id
    elif conversation_id:
        # Append new message to existing conversation

        result = self.conversations_collection.update_one(
            {"_id": ObjectId(conversation_id), "user": user_id},
            {
                "$push": {
                    "queries": {
                        "prompt": question,
                        "response": response,
                        "thought": thought,
                        "sources": sources,
                        "tool_calls": tool_calls,
                        "timestamp": current_time,
                        "attachments": attachment_ids,
                        "model_id": model_id,
                    }
                }
            },
        )

        if result.matched_count == 0:
            raise ValueError("Conversation not found or unauthorized")
        return conversation_id
    else:
        # Create new conversation

        messages_summary = [
            {
                "role": "system",
                "content": "You are a helpful assistant that creates concise conversation titles. "
                "Summarize conversations in 3 words or less using the same language as the user.",
            },
            {
                "role": "user",
                "content": "Summarise following conversation in no more than 3 words, "
                "respond ONLY with the summary, use the same language as the "
                "user query \n\nUser: " + question + "\n\n" + "AI: " + response,
            },
        ]

        completion = llm.gen(
            model=model_id, messages=messages_summary, max_tokens=30
        )

        conversation_data = {
            "user": user_id,
            "date": current_time,
            "name": completion,
            "queries": [
                {
                    "prompt": question,
                    "response": response,
                    "thought": thought,
                    "sources": sources,
                    "tool_calls": tool_calls,
                    "timestamp": current_time,
                    "attachments": attachment_ids,
                    "model_id": model_id,
                }
            ],
        }

        if api_key:
            if agent_id:
                conversation_data["agent_id"] = agent_id
                if is_shared_usage:
                    conversation_data["is_shared_usage"] = is_shared_usage
                    conversation_data["shared_token"] = shared_token
            agent = self.agents_collection.find_one({"key": api_key})
            if agent:
                conversation_data["api_key"] = agent["key"]
        result = self.conversations_collection.insert_one(conversation_data)
        return str(result.inserted_id)

