def render(self, gui: Gui, silent: t.Optional[bool] = False):
    if self._renderer is None:
        raise RuntimeError(f"Can't render page {self._route}: no renderer found")
    with warnings.catch_warnings(record=True) as w:
        warnings.resetwarnings()
        module_name = self._renderer._get_module_name()
        with gui._set_locals_context(module_name):  # type: ignore[attr-defined]
            self._rendered_jsx = self._renderer.render(gui)
        if silent:
            s = ""
            for wm in w:
                if wm.category is TaipyGuiAlwaysWarning:
                    s += f" - {wm.message}\n"
            if s:
                logging.warning("\033[1;31m\n" + s)

        else:
            if (
                self._rendered_jsx
                and isinstance(self._rendered_jsx, str)
                and (
                    result := _DETECT_CLOSING_TAGS.sub(
                        _SUBSTR_CLOSING_TAG,
                        self._rendered_jsx.replace(">style</TaipyStyle>", "/>"),
                    )
                )
            ):
                self._rendered_jsx = result
            if w:
                s = "\033[1;31m\n"
                s += (
                    message
                    := f"--- {len(w)} warning(s) were found for page '{'/' if self._route == gui._get_root_page_name() else self._route}' {self._renderer._get_content_detail(gui)} ---\n"  # type: ignore[reportAttributeAccessIssue] # noqa: E501
                )
                for i, wm in enumerate(w):
                    s += f" - Warning {i + 1}: {wm.message}\n"
                s += "-" * len(message)
                s += "\033[0m\n"
                logging.warning(s)
    if hasattr(self._renderer, "head"):
        self._head = list(self._renderer.head)  # type: ignore[attr-defined]
    # return renderer module_name from frame
    return module_name

def __send_var_list_update(  # noqa C901
    self,
    modified_vars: t.List[str],
    front_var: t.Optional[str] = None,
):
    ws_dict = {}
    is_custom_page = _Hooks()._is_in_custom_page_context()
    values = {v: _getscopeattr_drill(self, v) for v in modified_vars if is_custom_page or _is_moduled_variable(v)}  # type: ignore[arg-type]
    if not values:
        return
    for k, v in values.items():
        if isinstance(v, (_TaipyData, _TaipyContentHtml)) and v.get_name() in modified_vars:
            modified_vars.remove(v.get_name())
        elif isinstance(v, _DoNotUpdate):
            modified_vars.remove(k)
    custom_page_filtered_types = _Hooks()._get_resource_handler_data_layer_supported_types()
    in_custom_page_context = _Hooks()._is_in_custom_page_context()
    for _var in modified_vars:
        if not self.__is_front_end_variable(_var) and not in_custom_page_context:
            _TaipyLogger._get_logger().debug(f"Skipping variable '{_var}' not in front-end.")
            continue
        newvalue = values.get(_var)
        if isinstance(newvalue, (_TaipyData)) or (
            custom_page_filtered_types and isinstance(newvalue, custom_page_filtered_types)
        ):  # type: ignore
            newvalue = {"__taipy_refresh": True}
        else:
            is_json = False
            if isinstance(newvalue, (_TaipyContent, _TaipyContentImage)):
                ret_value = self.__get_content_accessor().get_info(
                    t.cast(str, front_var), newvalue.get(), isinstance(newvalue, _TaipyContentImage)
                )
                if isinstance(ret_value, tuple):
                    newvalue = f"/{Gui._CONTENT_ROOT}/{ret_value[0]}"
                else:
                    newvalue = ret_value
            elif isinstance(newvalue, _TaipyContentHtml):
                newvalue = self._get_user_content_url(
                    None, {"variable_name": str(_var), Gui._HTML_CONTENT_KEY: str(time.time())}
                )
            elif isinstance(newvalue, (_TaipyLov, _TaipyLovValue)):
                newvalue = self.__adapter.run(
                    newvalue.get_name(), newvalue.get(), id_only=isinstance(newvalue, _TaipyLovValue)
                )
            elif isinstance(newvalue, _TaipyBase):
                is_json = isinstance(newvalue, _TaipyToJson)
                newvalue = newvalue.get()
            # Skip in taipy-gui, available in custom frontend
            if isinstance(newvalue, (dict, _MapDict)) and not in_custom_page_context and not is_json:
                continue
            if isinstance(newvalue, float) and math.isnan(newvalue):
                # do not let NaN go through json, it is not handle well (dies silently through websocket)
                newvalue = None
            if newvalue is not None and not isinstance(newvalue, str) and not is_json:
                debug_warnings: t.List[warnings.WarningMessage] = []
                with warnings.catch_warnings(record=True) as warns:
                    warnings.resetwarnings()
                    json.dumps(newvalue, cls=_TaipyJsonEncoder)
                    if len(warns):
                        keep_value = True
                        for w in warns:
                            if is_debugging():
                                debug_warnings.append(w)
                            if w.category is not DeprecationWarning and w.category is not PendingDeprecationWarning:
                                keep_value = False
                                break
                        if not keep_value:
                            # do not send data that is not serializable
                            continue
                for w in debug_warnings:
                    warnings.warn(w.message, w.category)  # noqa: B028
        ws_dict[_var] = newvalue
    # TODO: What if value == newvalue?
    self.__send_ws_update_with_dict(ws_dict)

def __send_ws(self, payload: dict, allow_grouping=True, send_back_only=False) -> None:
    grouping_message = self.__get_message_grouping() if allow_grouping else None
    if grouping_message is None:
        try:
            self._server.send_ws_message(
                data=payload,
                to=t.cast(str, self.__get_ws_receiver(send_back_only)),
            )
            time.sleep(0.001)
        except Exception as e:  # pragma: no cover
            _warn(f"Exception raised in WebSocket communication in '{self.__frame.f_code.co_name}'", e)
    else:
        grouping_message.append(payload)

def _serve_extension(self, path: str) -> t.Any:
    parts = path.split("/")
    last_error = ""
    resource_name = None
    if len(parts) > 1:
        libs = Gui.__extensions.get(parts[0], [])
        for library in libs:
            try:
                resource_name = library.get_resource("/".join(parts[1:]))
                if resource_name:
                    return self._server.send_file(resource_name)
            except Exception as e:
                last_error = f"\n{e}"  # Check if the resource is served by another library with the same name
    _warn(f"Resource '{resource_name or path}' not accessible for library '{parts[0]}'{last_error}")
    return self._server.create_http_response("", 404)

def __pre_render_pages(self) -> None:
    """Pre-render all pages to have a proper initialization of all variables"""
    self.__set_client_id_in_context()
    scope_metadata = self._get_data_scope_metadata()
    if scope_metadata[_DataScopes._META_PRE_RENDER]:
        return
    for page in self._config.pages:
        if page is not None:
            with contextlib.suppress(Exception):
                if (
                    page._renderer is not None
                    and _Hooks()._get_custom_page_type()
                    and isinstance(page._renderer, _Hooks()._get_custom_page_type())  # type: ignore[arg-type]
                ):
                    _Hooks()._bind_custom_page_variables(self, page._renderer, self._get_client_id())
                else:
                    page.render(self, silent=True)  # type: ignore[arg-type]
    if additional_pages := _Hooks()._get_additional_pages():
        for page in additional_pages:
            if isinstance(page, Page):
                with contextlib.suppress(Exception):
                    if (
                        page._renderer is not None
                        and _Hooks()._get_custom_page_type()
                        and isinstance(page, _Hooks()._get_custom_page_type())  # type: ignore[arg-type]
                    ):
                        _Hooks()._bind_custom_page_variables(self, page, self._get_client_id())
                    else:
                        new_page = _Page()
