def _format_mcp_result(self, result: Any) -> str:
	"""Format MCP tool result into a string for ActionResult.

	Args:
		result: Raw result from MCP tool call

	Returns:
		Formatted string representation of the result
	"""
	# Handle different MCP result formats
	if hasattr(result, 'content'):
		# Structured content response
		if isinstance(result.content, list):
			# Multiple content items
			parts = []
			for item in result.content:
				if hasattr(item, 'text'):
					parts.append(item.text)
				elif hasattr(item, 'type') and item.type == 'text':
					parts.append(str(item))
				else:
					parts.append(str(item))
			return '\n'.join(parts)
		else:
			return str(result.content)
	elif isinstance(result, list):
		# List of content items
		parts = []
		for item in result:
			if hasattr(item, 'text'):
				parts.append(item.text)
			else:
				parts.append(str(item))
		return '\n'.join(parts)
	else:
		# Direct result or unknown format
		return str(result)

def _json_schema_to_python_type(self, schema: dict, model_name: str = 'NestedModel') -> Any:
	"""Convert JSON Schema type to Python type.

	Args:
		schema: JSON Schema definition
		model_name: Name for nested models

	Returns:
		Python type corresponding to the schema
	"""
	json_type = schema.get('type', 'string')

	# Basic type mapping
	type_mapping = {
		'string': str,
		'number': float,
		'integer': int,
		'boolean': bool,
		'array': list,
		'null': type(None),
	}

	# Handle enums (they're still strings)
	if 'enum' in schema:
		return str

	# Handle objects with nested properties
	if json_type == 'object':
		properties = schema.get('properties', {})
		if properties:
			# Create nested pydantic model for objects with properties
			nested_fields = {}
			required_fields = set(schema.get('required', []))

			for prop_name, prop_schema in properties.items():
				# Recursively process nested properties
				prop_type = self._json_schema_to_python_type(prop_schema, f'{model_name}_{prop_name}')

				# Determine if field is required and handle defaults
				if prop_name in required_fields:
					default = ...  # Required field
				else:
					# Optional field - make type optional and handle default
					prop_type = prop_type | None
					if 'default' in prop_schema:
						default = prop_schema['default']
					else:
						default = None

				# Add field with description if available
				field_kwargs = {}
				if 'description' in prop_schema:
					field_kwargs['description'] = prop_schema['description']

				nested_fields[prop_name] = (prop_type, Field(default, **field_kwargs))

			# Create a BaseModel class with proper configuration
			class ConfiguredBaseModel(BaseModel):
				model_config = ConfigDict(extra='forbid', validate_by_name=True, validate_by_alias=True)

			try:
				# Create and return nested pydantic model
				return create_model(model_name, __base__=ConfiguredBaseModel, **nested_fields)
			except Exception as e:
				logger.error(f'Failed to create nested model {model_name}: {e}')
				logger.debug(f'Fields: {nested_fields}')
				# Fallback to basic dict if model creation fails
				return dict
		else:
			# Object without properties - just return dict
			return dict

	# Handle arrays with specific item types
	if json_type == 'array':
		if 'items' in schema:
			# Get the item type recursively
			item_type = self._json_schema_to_python_type(schema['items'], f'{model_name}_item')
			# Return properly typed list
			return list[item_type]
		else:
			# Array without item type specification
			return list

	# Get base type for non-object types
	base_type = type_mapping.get(json_type, str)

	# Handle nullable/optional types
	if schema.get('nullable', False) or json_type == 'null':
		return base_type | None

	return base_type

def setup_test_environment():
	"""
	Automatically set up test environment for all tests.
	"""

	# Create a temporary directory for test config
	config_dir = tempfile.mkdtemp(prefix='browseruse_tests_')

	original_env = {}
	test_env_vars = {
		'SKIP_LLM_API_KEY_VERIFICATION': 'true',
		'ANONYMIZED_TELEMETRY': 'false',
		'BROWSER_USE_CLOUD_SYNC': 'true',
		'BROWSER_USE_CLOUD_API_URL': 'http://placeholder-will-be-replaced-by-specific-test-fixtures',
		'BROWSER_USE_CLOUD_UI_URL': 'http://placeholder-will-be-replaced-by-specific-test-fixtures',
		'BROWSER_USE_CONFIG_DIR': config_dir,
	}

	for key, value in test_env_vars.items():
		original_env[key] = os.environ.get(key)
		os.environ[key] = value

	yield

	# Restore original environment
	for key, value in original_env.items():
		if value is None:
			os.environ.pop(key, None)
		else:
			os.environ[key] = value

def _setup_handlers(self):
	"""Setup MCP server handlers."""

	@self.server.list_tools()
	async def handle_list_tools() -> list[types.Tool]:
		"""List available test tools."""
		return [
			types.Tool(
				name='count_to_n',
				description='Count from 1 to n and return the numbers',
				inputSchema={
					'type': 'object',
					'properties': {'n': {'type': 'integer', 'description': 'Number to count to'}},
					'required': ['n'],
				},
			),
			types.Tool(
				name='echo_message',
				description='Echo back a message with a prefix',
				inputSchema={
					'type': 'object',
					'properties': {
						'message': {'type': 'string', 'description': 'Message to echo'},
						'prefix': {'type': 'string', 'description': 'Prefix to add', 'default': 'Echo:'},
					},
					'required': ['message'],
				},
			),
			types.Tool(
				name='get_test_data',
				description='Get some test data as JSON',
				inputSchema={'type': 'object', 'properties': {}},
			),
			types.Tool(
				name='process_trace_update',
				description='Process a cognitive trace update with nested object parameter',
				inputSchema={
					'type': 'object',
					'properties': {
						'trace': {
							'type': 'object',
							'properties': {
								'recent_actions': {
									'type': 'array',
									'items': {'type': 'string'},
									'description': 'List of recent action names',
								},
								'current_context': {
									'type': 'string',
									'description': 'Current environment context or state',
								},
								'goal': {
									'type': 'string',
									'description': 'Current goal being pursued',
								},
							},
							'required': ['recent_actions', 'goal'],
							'additionalProperties': False,
						},
						'window_size': {
							'type': 'number',
							'description': 'Size of the monitoring window',
							'default': 10,
						},
					},
					'required': ['trace'],
					'additionalProperties': False,
				},
			),
			types.Tool(
				name='process_array_data',
				description='Process various array types',
				inputSchema={
					'type': 'object',
					'properties': {
						'string_list': {
							'type': 'array',
							'items': {'type': 'string'},
							'description': 'List of strings',
						},
						'number_list': {
							'type': 'array',
							'items': {'type': 'number'},
							'description': 'List of numbers',
						},
						'config_list': {
							'type': 'array',
							'items': {
								'type': 'object',
								'properties': {
									'name': {'type': 'string'},
									'value': {'type': 'integer'},
									'enabled': {'type': 'boolean', 'default': True},
								},
								'required': ['name', 'value'],
							},
							'description': 'List of configuration objects',
						},
						'simple_array': {
							'type': 'array',
							'description': 'Array without item type specified',
						},
					},
					'required': ['string_list'],
				},
			),
		]

	@self.server.call_tool()
	async def handle_call_tool(name: str, arguments: dict | None) -> list[types.TextContent]:
		"""Handle tool execution."""
		# Record the call
		self.call_history.append({'tool': name, 'arguments': arguments or {}})

		if name == 'count_to_n':
			assert arguments is not None
			n = arguments.get('n', 5)
			numbers = ', '.join(str(i) for i in range(1, n + 1))
			result = f'Counted to {n}: {numbers}'

		elif name == 'echo_message':
			assert arguments is not None
			message = arguments.get('message', '')
			prefix = arguments.get('prefix', 'Echo:')
			result = f'{prefix} {message}'

		elif name == 'get_test_data':
			data = {'status': 'success', 'items': ['apple', 'banana', 'cherry'], 'count': 3}
			result = json.dumps(data, indent=2)

		elif name == 'process_trace_update':
			assert arguments is not None
			trace = arguments.get('trace', {})
			window_size = arguments.get('window_size', 10)

			recent_actions = trace.get('recent_actions', [])
			current_context = trace.get('current_context', 'unknown')
			goal = trace.get('goal', 'no goal')

			result = f'Processed trace update: {len(recent_actions)} actions, goal: {goal}, context: {current_context}, window: {window_size}'

		elif name == 'process_array_data':
			assert arguments is not None
			string_list = arguments.get('string_list', [])
			number_list = arguments.get('number_list', [])
			config_list = arguments.get('config_list', [])
			simple_array = arguments.get('simple_array', [])

			config_summary = f'{len(config_list)} configs' if config_list else 'no configs'
