						e.target.style.opacity = '1';
						updateStatus();
					});

					// Events for the dropzones
					dropzones.forEach(zone => {
						zone.addEventListener('dragover', (e) => {
							e.preventDefault(); // Allow drop
							logEvent(e);
							zone.style.backgroundColor = '#f0f0f0';
