    def _upload_recipe(self, ref, base_files=None):

        files = {"conanfile.py": GenConanfile("3").with_requires("1", "12")}
        if base_files:
            files.update(base_files)
        content = """
from conan import ConanFile

class MyConan(ConanFile):
    name = "%s"
    version = "%s"
    settings = arch, compiler, os
""" % (ref.name, ref.version)
        files[CONANFILE] = content
        files_md5s = {filename: md5(content) for filename, content in files.items()}
        conan_digest = FileTreeManifest(123123123, files_md5s)

        tmp_dir = temp_folder()
        abs_paths = {}
        for filename, content in files.items():
            abs_path = os.path.join(tmp_dir, filename)
            save(abs_path, content)
            abs_paths[filename] = abs_path
        abs_paths[CONAN_MANIFEST] = os.path.join(tmp_dir, CONAN_MANIFEST)
        conan_digest.save(tmp_dir)

        self.api.upload_recipe(ref, abs_paths)

def _get(self, ref):
    full_query = self._build_query(ref)
    try:
        response = self._session.post(
            self._query_url,
            headers=_build_headers(self._token),
            json={
                "query": textwrap.dedent(full_query)
            }
        )

        if response.status_code == 404:
            ConanOutput().write("\n")
            ConanOutput().warning(
                f"An error occurred while connecting to the '{self.name}' provider.\n"
                "This is likely because your JFrog Platform instance does not have JFrog Curation.\n"
                "For more information, visit: https://audit.conan.io/missing-curation\n"
            )

        # Raises if some HTTP error was found
        response.raise_for_status()
    except Exception as e:
        raise e

    response_json = response.json()
    # filter the extensions key with graphql data
    response_json.pop('extensions', None)

    if "errors" in response_json:
        return {"error": self._parse_error(response_json["errors"], ref)}
    return response_json

def _parse_error(errors, ref):
    """This function removes the errors array that comes from the catalog and returns a
    more user-friendly message if we know how to parse it, or a generic one if we don't
    find such one"""

    def _replace_message(message):
        if "not found" in message:
            return f"Package '{ref}' not scanned: Not found."
        return None

    error_msgs = filter(bool, [_replace_message(error["message"]) for error in errors])
    return next(error_msgs, "Unknown error")

def get_cves(self, refs):
    if not self._token:
        raise ConanException(f"Missing authentication token for '{self.name}' provider.\n"
                             f"Please authenticate using 'conan audit provider auth' and retry.")

    result = {"data": {}, "error": None}

    for ref in refs:
        try:
            response = self._get(ref)
            if "error" in response:
                result["data"][str(ref)] = {"error": {"details": response["error"]}}
            else:
                result["data"][str(ref)] = response.get("data",{}).get("query",{})
        except Exception as e:
            result["conan_error"] = str(e)
            break

    return result

def show(self, fnpattern, pattern=""):
    return {key: self.get(key)
            for key in self._values.keys()
            if fnmatch.fnmatch(pattern + key, fnpattern)}

def _split_pattern_name(pattern_name):
    if pattern_name.count(":") >= 2:
        pattern, name = pattern_name.split(":", 1)
    else:
        pattern, name = None, pattern_name
    return pattern, name

def loads(self, text, profile=False):
    self._pattern_confs = {}

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        for op, method in ConfDefinition.actions:
            tokens = line.split(op, 1)
            if len(tokens) != 2:
                continue
            pattern_name, value = tokens
            parsed_value = ConfDefinition._get_evaluated_value(value)
            self.update(pattern_name, parsed_value, profile=profile, method=method)
            break
        else:
            raise ConanException("Bad conf definition: {}".format(line))

def _get_defines(cpp_info):
    return ['"{}"'.format(define.replace('"', '\\' * 3 + '"'))
            for define in cpp_info.defines]

def get_full_libs_info(self):
    full_libs_info = defaultdict(list)
    cpp_info = self._dep.cpp_info
    deduced_cpp_info = cpp_info.deduce_full_cpp_info(self._dep)
    package_folder_path = self.package_folder
    # Root
    if len(cpp_info.libs) > 1:
        for lib_name in cpp_info.libs:
            virtual_component = deduced_cpp_info.components.pop(f"_{lib_name}")  # removing it!
            full_libs_info["root"].append(
                _LibInfo(lib_name, virtual_component, package_folder_path)
            )
    elif cpp_info.libs:
        full_libs_info["root"].append(
            _LibInfo(cpp_info.libs[0], deduced_cpp_info, package_folder_path)
        )
    # components
    for cmp_name, cmp_cpp_info in deduced_cpp_info.components.items():
        if cmp_name == "_common":  # FIXME: placeholder?
            continue
        if len(cmp_cpp_info.libs) > 1:
            raise ConanException(f"BazelDeps only allows 1 lib per component:\n"
                                 f"{self._dep}: {cmp_cpp_info.libs}")
        elif cmp_cpp_info.libs:
            # Bazel needs to relativize each path
            full_libs_info[_get_component_name(self._dep, cmp_name)].append(
                _LibInfo(cmp_cpp_info.libs[0], cmp_cpp_info, package_folder_path)
            )
    return full_libs_info

def test_conan_audit_private():
    successful_response = {
        "data": {
            "query": {
                "vulnerabilities": {
                    "totalCount": 1,
                    "edges": [
                        {
                            "node": {
                                "name": "CVE-2023-45853",
                                "description": "Zip vulnerability",
                                "severity": "Critical",
                                "cvss": {
                                    "preferredBaseScore": 8.9
                                },
                                "aliases": [
                                    "CVE-2023-45853",
                                    "JFSA-2023-000272529"
                                ],
                                "advisories": [
                                    {
                                        "name": "CVE-2023-45853"
                                    },
                                    {
                                        "name": "JFSA-2023-000272529"
                                    }
                                ],
                                "references": [
                                    "https://pypi.org/project/pyminizip/#history",
                                ]
                            }
                        }
                    ]
                }
            }
        }
    }

    tc = TestClient(light=True)

    tc.save({"conanfile.py": GenConanfile("zlib", "1.2.11")})
    tc.run("export .")

    tc.run("list '*' -f=json", redirect_stdout="pkglist.json")

    # TODO: If the CLI does not allow tokenless provider, should this case not be handled?
    tc.run("audit provider add myprivate --url=foo --type=private --token=f")
    # Now, remove the token as if the user didn't set it manually in the json
    providers = json.loads(tc.load_home("audit_providers.json"))
    providers["myprivate"].pop("token", None)
    tc.save_home({"audit_providers.json": json.dumps(providers)})

    tc.run("audit list zlib/1.2.11 -p=myprivate", assert_error=True)
    assert "Missing authentication token for 'myprivate' provider" in tc.out

    tc.run("audit provider auth myprivate --token=valid_token")

    with proxy_response(200, successful_response):
        tc.run("audit list zlib/1.2.11 -p=myprivate")
        assert "zlib/1.2.11 1 vulnerability found" in tc.out

        tc.run("audit list -l=pkglist.json -p=myprivate")
        assert "zlib/1.2.11 1 vulnerability found" in tc.out

        tc.run("audit scan --requires=zlib/1.2.11  -p=myprivate")
        assert "zlib/1.2.11 1 vulnerability found" in tc.out

    # Now some common errors, like rate limited or missing lib, but it should not fail!
    with proxy_response(400, {"errors": [{"message": "Ref not found"}]}):
        # Not finding a package should not be an error
        tc.run("audit list zlib/1.2.11 -p=myprivate")
        assert "Package 'zlib/1.2.11' not scanned: Not found." in tc.stdout

    with proxy_response(403, {"errors": [{"message": "Authentication error"}]}):
        tc.run("audit list zlib/1.2.11 -p=myprivate")
        assert "Unknown error" in tc.out

    with proxy_response(500, {"errors": [{"message": "Internal error"}]}):
        tc.run("audit list zlib/1.2.11 -p=myprivate")
        assert "Unknown error" in tc.out

    with proxy_response(405, {"errors": [{"message": "Method not allowed"}]}):
        tc.run("audit list zlib/1.2.11 -p=myprivate")
        assert "Unknown error" in tc.out

    with proxy_response(404, {"errors": [{"message": "Not found"}]}):
        tc.run("audit list zlib/1.2.11 -p=myprivate")
        assert "An error occurred while connecting to the 'myprivate' provider" in tc.out

